{"command":"cat > /workspace/src/parser.rs <<'EOF'
// Line-level parser for argc comment tags.

#[derive(Debug, Clone, PartialEq)]
pub enum ChoiceValue {
    Values(Vec<String>),
    Fn(String, bool),
}

#[derive(Debug, Clone, PartialEq)]
pub enum DefaultValue {
    Value(String),
    Fn(String),
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Modifier {
    Optional,
    Required,
    MultipleOptional(Option<char>),
    MultipleRequired(Option<char>),
    Terminated,
}

#[derive(Debug, Clone)]
pub struct ParamData {
    pub name: String,
    pub modifier: Modifier,
    pub choice: Option<ChoiceValue>,
    pub default: Option<DefaultValue>,
}

#[derive(Debug, Clone)]
pub struct RawFlagOption {
    pub data: ParamData,
    pub flag: bool,
    pub short: Option<String>,
    pub long_prefix: String,
    pub prefixed: bool,
    pub assigned: bool,
    pub env: Option<String>, // "$$" means auto
    pub notations: Vec<String>,
    pub describe: String,
}

#[derive(Debug, Clone)]
pub struct RawPositional {
    pub data: ParamData,
    pub env: Option<String>,
    pub notation: Option<String>,
    pub describe: String,
}

#[derive(Debug, Clone)]
pub struct RawEnv {
    pub data: ParamData,
    pub describe: String,
}

#[derive(Debug, Clone)]
pub enum EventData {
    Describe(String),
    Version(String),
    Meta(String, Option<String>),
    Cmd(String),
    Aliases(Vec<String>),
    FlagOption(RawFlagOption),
    Positional(RawPositional),
    Env(RawEnv),
    Func(String),
    Unknown(String),
}

#[derive(Debug, Clone)]
pub struct Event {
    pub data: EventData,
    pub position: usize,
}

pub fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ':' | '@')
}

fn is_space(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn space1(s: &str) -> Option<&str> {
    let r = s.trim_start_matches(is_space);
    if r.len() == s.len() {
        None
    } else {
        Some(r)
    }
}

fn space0(s: &str) -> &str {
    s.trim_start_matches(is_space)
}

fn take_while1(s: &str, f: impl Fn(char) -> bool) -> Option<(&str, &str)> {
    let mut end = 0;
    for (i, c) in s.char_indices() {
        if f(c) {
            end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if end == 0 {
        None
    } else {
        Some((&s[..end], &s[end..]))
    }
}

fn take_while(s: &str, f: impl Fn(char) -> bool) -> (&str, &str) {
    let mut end = 0;
    for (i, c) in s.char_indices() {
        if f(c) {
            end = i + c.len_utf8();
        } else {
            break;
        }
    }
    (&s[..end], &s[end..])
}

fn ends_token(s: &str) -> bool {
    s.is_empty() || s.starts_with(is_space)
}

pub fn parse(source: &str) -> Result<Vec<Event>, String> {
    let mut result: Vec<Event> = vec![];
    let lines: Vec<&str> = source.lines().collect();
    let mut idx = 0;
    while idx < lines.len() {
        let line = lines[idx];
        let position = idx + 1;
        match parse_line(line) {
            Some(Some(mut data)) => {
                // multiline continuation
                let describable = matches!(
                    data,
                    EventData::Describe(_)
                        | EventData::Cmd(_)
                        | EventData::FlagOption(_)
                        | EventData::Positional(_)
                        | EventData::Env(_)
                );
                if describable {
                    let mut extra: Vec<String> = vec![];
                    while idx + 1 < lines.len() {
                        let next = lines[idx + 1];
                        if parse_line(next).is_some() {
                            break;
                        }
                        if let Some(text) = parse_normal_comment(next) {
                            extra.push(text.to_string());
                            idx += 1;
                        } else {
                            break;
                        }
                    }
                    if !extra.is_empty() {
                        append_describe(&mut data, &extra);
                    }
                }
                finalize_describe(&mut data);
                result.push(Event { data, position });
            }
            Some(None) => return Err(format!("syntax error at line {}", position)),
            None => {}
        }
        idx += 1;
    }
    Ok(result)
}

fn append_describe(data: &mut EventData, extra: &[String]) {
    let target: &mut String = match data {
        EventData::Describe(t) => t,
        EventData::Cmd(t) => t,
        EventData::FlagOption(p) => &mut p.describe,
        EventData::Positional(p) => &mut p.describe,
        EventData::Env(p) => &mut p.describe,
        _ => return,
    };
    for line in extra {
        target.push('\n');
        target.push_str(line);
    }
}

fn finalize_describe(data: &mut EventData) {
    let target: &mut String = match data {
        EventData::Describe(t) => t,
        EventData::Cmd(t) => t,
        EventData::FlagOption(p) => &mut p.describe,
        EventData::Positional(p) => &mut p.describe,
        EventData::Env(p) => &mut p.describe,
        _ => return,
    };
    *target = target.trim().to_string();
}

fn parse_normal_comment(line: &str) -> Option<&str> {
    let rest = line.trim_start_matches('#');
    if rest.len() == line.len() {
        return None;
    }
    let mut chars = rest.chars();
    match chars.next() {
        Some(c) if is_space(c) => Some(&rest[c.len_utf8()..]),
        _ => Some(rest),
    }
}

/// None => not a tag/fn line; Some(None) => syntax error; Some(Some(data)) => event
pub fn parse_line(line: &str) -> Option<Option<EventData>> {
    if let Some(r) = parse_tag(line) {
        return Some(r);
    }
    if let Some(name) = parse_fn(line) {
        return Some(Some(EventData::Func(name)));
    }
    None
}

fn is_fn_name_char(c: char) -> bool {
    !(c.is_whitespace()
        || matches!(
            c,
            '$' | '[' | ']' | '{' | '}' | '&' | ';' | '<' | '>' | '|' | '"' | '\'' | '`' | '\\' | '(' | ')'
        ))
}

fn parse_fn(line: &str) -> Option<String> {
    // function NAME
    if let Some(rest) = line.strip_prefix("function") {
        if let Some(rest) = space1(rest) {
            if let Some((name, _)) = take_while1(rest, is_fn_name_char) {
                return Some(name.to_string());
            }
        }
    }
    // NAME ( )
    let (name, rest) = take_while1(line, is_fn_name_char)?;
    let rest = space0(rest);
    let rest = rest.strip_prefix('(')?;
    let rest = space0(rest);
    rest.strip_prefix(')')?;
    Some(name.to_string())
}

fn parse_tag(line: &str) -> Option<Option<EventData>> {
    let rest = line.trim_start_matches('#');
    if rest.len() == line.len() {
        return None;
    }
    let rest = space0(rest);
    let rest = rest.strip_prefix('@')?;
    // text tags
    for (tag, kind) in [("describe", 0), ("version", 1), ("cmd", 2)] {
        if let Some(after) = rest.strip_prefix(tag) {
            let text = if after.is_empty() {
                Some("")
            } else {
                space1(after)
            };
            if let Some(text) = text {
                let text = text.to_string();
                let data = match kind {
                    0 => EventData::Describe(text),
                    1 => EventData::Version(text.trim().to_string()),
                    _ => EventData::Cmd(text),
                };
                return Some(Some(data));
            }
        }
    }
    // param tags
    for tag in ["flag", "option", "arg", "env"] {
        if let Some(after) = rest.strip_prefix(tag) {
            let parsed = space1(after).and_then(|input| match tag {
                "flag" => parse_flag_option_param(input, true).map(EventData::FlagOption),
                "option" => parse_flag_option_param(input, false).map(EventData::FlagOption),
                "arg" => parse_positional_param(input).map(EventData::Positional),
                _ => parse_env_param(input).map(EventData::Env),
            });
            return Some(parsed);
        }
    }
    // meta
    if let Some(after) = rest.strip_prefix("meta") {
        if let Some(input) = space1(after) {
            return Some(parse_meta(input));
        }
    }
    // alias
    if let Some(after) = rest.strip_prefix("alias") {
        if let Some(input) = space1(after) {
            if let Some(list) = parse_aliases(input) {
                return Some(Some(EventData::Aliases(list)));
            }
        }
    }
    let (name, _) = take_while(rest, |c| !c.is_whitespace());
    Some(Some(EventData::Unknown(name.to_string())))
}

fn parse_meta(input: &str) -> Option<EventData> {
    let (name, rest) = take_while1(input, is_name_char)?;
    if rest.is_empty() {
        return Some(EventData::Meta(name.to_string(), None));
    }
    let rest = space1(rest)?;
    let value = rest.trim();
    if value.is_empty() {
        Some(EventData::Meta(name.to_string(), None))
    } else {
        Some(EventData::Meta(name.to_string(), Some(value.to_string())))
    }
}

fn parse_aliases(input: &str) -> Option<Vec<String>> {
    let (first, mut rest) = take_while1(input, is_name_char)?;
    let mut list = vec![first.to_string()];
    loop {
        let Some(r) = rest.strip_prefix(',') else { break };
        let r = space0(r);
        match take_while1(r, is_name_char) {
            Some((name, r2)) => {
                list.push(name.to_string());
                rest = r2;
            }
            None => break,
        }
    }
    Some(list)
}

fn parse_modifier(input: &str, allow_multi: bool) -> (Modifier, &str) {
    let delim = |s: &str| -> (Option<char>, usize) {
        match s.chars().next() {
            Some(c) if matches!(c, ',' | ':' | ';' | '@' | '|' | '/') => (Some(c), 1),
            _ => (None, 0),
        }
    };
    if let Some(r) = input.strip_prefix('!') {
        return (Modifier::Required, r);
    }
    if allow_multi {
        if let Some(r) = input.strip_prefix('*') {
            let (d, n) = delim(r);
            return (Modifier::MultipleOptional(d), &r[n..]);
        }
        if let Some(r) = input.strip_prefix('+') {
            let (d, n) = delim(r);
            return (Modifier::MultipleRequired(d), &r[n..]);
        }
        if let Some(r) = input.strip_prefix('~') {
            return (Modifier::Terminated, r);
        }
    }
    (Modifier::Optional, input)
}

fn parse_fn_name(input: &str) -> Option<(&str, &str)> {
    let r = input.strip_prefix('`')?;
    let (name, r) = take_while1(r, is_name_char)?;
    let r = r.strip_prefix('`')?;
    Some((name, r))
}

fn parse_quoted(input: &str) -> Option<(String, &str)> {
    let q = input.chars().next()?;
    if q != '"' && q != '\'' {
        return None;
    }
    let body = &input[1..];
    let mut chars = body.char_indices();
    let mut end = None;
    while let Some((i, c)) = chars.next() {
        if c == '\\' {
            chars.next();
            continue;
        }
        if c == q {
            end = Some(i);
            break;
        }
    }
    let end = end?;
    Some((body[..end].to_string(), &body[end + 1..]))
}

fn parse_default(input: &str) -> Option<(DefaultValue, &str)> {
    let r = input.strip_prefix('=')?;
    if let Some((name, rest)) = parse_fn_name(r) {
        return Some((DefaultValue::Fn(name.to_string()), rest));
    }
    if let Some((value, rest)) = parse_quoted(r) {
        return Some((DefaultValue::Value(value), rest));
    }
    let (value, rest) = take_while(r, |c| !c.is_whitespace());
    Some((DefaultValue::Value(value.to_string()), rest))
}

fn parse_choice_value(input: &str) -> (String, &str) {
    if let Some((v, rest)) = parse_quoted(input) {
        return (v, rest);
    }
    let (v, rest) = take_while(input, |c| c != '|' && c != ']');
    (v.to_string(), rest)
}

fn parse_choice_values(input: &str) -> Option<(Vec<String>, &str)> {
    let mut values = vec![];
    let (v, mut rest) = parse_choice_value(input);
    values.push(v);
    while let Some(r) = rest.strip_prefix('|') {
        let (v, r2) = parse_choice_value(r);
        values.push(v);
        rest = r2;
    }
    Some((values, rest))
}

// returns (choice, default, rest)
fn parse_choices(input: &str) -> Option<(ChoiceValue, Option<DefaultValue>, &str)> {
    let r = input.strip_prefix('[')?;
    // choice fn
    {
        let (skip, r2) = match r.strip_prefix('?') {
            Some(r2) => (true, r2),
            None => (false, r),
        };
        if let Some((name, r3)) = parse_fn_name(r2) {
            if let Some(r4) = r3.strip_prefix(']') {
                return Some((ChoiceValue::Fn(name.to_string(), !skip), None, r4));
            }
            return None;
        }
    }
    if let Some(r2) = r.strip_prefix('=') {
        let (values, rest) = parse_choice_values(r2)?;
        if values.len() < 2 {
            return None;
        }
        let rest = rest.strip_prefix(']')?;
        let default = values[0].clone();
        return Some((ChoiceValue::Values(values), Some(DefaultValue::Value(default)), rest));
    }
    let (values, rest) = parse_choice_values(r)?;
    let rest = rest.strip_prefix(']')?;
    Some((ChoiceValue::Values(values), None, rest))
}

fn parse_param_tail_value(
    input: &str,
    modifier: Modifier,
    allow_default: bool,
) -> Option<(Option<ChoiceValue>, Option<DefaultValue>, &str)> {
    if input.starts_with('[') {
        let (c, d, rest) = parse_choices(input)?;
        return Some((Some(c), d, rest));
    }
    if allow_default && modifier == Modifier::Optional && input.starts_with('=') {
        let (d, rest) = parse_default(input)?;
        return Some((None, Some(d), rest));
    }
    Some((None, None, input))
}

fn parse_env_binding(input: &str) -> (Option<String>, &str) {
    if let Some(r) = space1(input) {
        if let Some(r2) = r.strip_prefix('$') {
            if let Some(r3) = r2.strip_prefix('$') {
                return (Some("$$".to_string()), r3);
            }
            if let Some((name, r3)) = take_while1(r2, |c| c.is_ascii_uppercase() || c == '_') {
                return (Some(name.to_string()), r3);
            }
        }
    }
    (None, input)
}

fn parse_notation(input: &str) -> Option<(String, &str)> {
    let r = input.strip_prefix('<')?;
    let (v, r) = take_while(r, |c| c != '>');
    let r = r.strip_prefix('>')?;
    if !ends_token(r) {
        return None;
    }
    Some((v.to_string(), r))
}

fn parse_describe(input: &str) -> Option<String> {
    if input.is_empty() {
        return Some(String::new());
    }
    let r = space1(input)?;
    Some(r.to_string())
}

fn parse_positional_param(input: &str) -> Option<RawPositional> {
    let (name, rest) = take_while1(input, is_name_char)?;
    let (modifier, rest) = parse_modifier(rest, true);
    let (choice, default, rest) = parse_param_tail_value(rest, modifier, true)?;
    if !ends_token(rest) {
        return None;
    }
    let (env, rest) = parse_env_binding(rest);
    if !ends_token(rest) {
        return None;
    }
    let mut notation = None;
    let mut rest = rest;
    if let Some(r) = space1(rest) {
        if let Some((n, r2)) = parse_notation(r) {
            notation = Some(n);
            rest = r2;
        }
    }
    let describe = parse_describe(rest)?;
    Some(RawPositional {
        data: ParamData { name: name.to_string(), modifier, choice, default },
        env,
        notation,
        describe,
    })
}

fn parse_env_param(input: &str) -> Option<RawEnv> {
    let (name, rest) = take_while1(input, is_name_char)?;
    let (modifier, rest) = parse_modifier(rest, true);
    let (choice, default, rest) = parse_param_tail_value(rest, modifier, true)?;
    let describe = parse_describe(rest)?;
    Some(RawEnv {
        data: ParamData { name: name.to_string(), modifier, choice, default },
        describe,
    })
}

fn parse_short(input: &str) -> Option<(String, &str)> {
    let mut chars = input.chars();
    let p = chars.next()?;
    if p != '-' && p != '+' {
        return None;
    }
    let c = chars.next()?;
    if !is_name_char(c) || c == '-' {
        return None;
    }
    let rest = &input[1 + c.len_utf8()..];
    let rest = space1(rest)?;
    Some((format!("{}{}", p, c), rest))
}

fn parse_flag_option_param(input: &str, flag: bool) -> Option<RawFlagOption> {
    if let Some((short, rest)) = parse_short(input) {
        if let Some(mut p) = parse_long_part(rest, flag) {
            p.short = Some(short);
            return Some(p);
        }
    }
    parse_long_part(input, flag)
}

fn parse_long_part(input: &str, flag: bool) -> Option<RawFlagOption> {
    let (prefix, rest) = if let Some(r) = input.strip_prefix("--") {
        ("--", r)
    } else if let Some(r) = input.strip_prefix('-') {
        ("-", r)
    } else if let Some(r) = input.strip_prefix('+') {
        ("+", r)
    } else {
        return None;
    };
    let (mut name, rest) = take_while(rest, is_name_char);
    if name.is_empty() {
        return None;
    }
    let mut prefixed = false;
    let mut assigned = false;
    if name.ends_with('-') {
        prefixed = true;
        name = &name[..name.len() - 1];
    } else if name.ends_with(':') {
        assigned = true;
        name = &name[..name.len() - 1];
    }
    if name.is_empty() && prefix != "-" {
        return None;
    }
    let (modifier, rest) = if flag {
        match rest.strip_prefix('*') {
            Some(r) => (Modifier::MultipleOptional(None), r),
            None => (Modifier::Optional, rest),
        }
    } else {
        parse_modifier(rest, true)
    };
    let (choice, default, rest) = if flag {
        (None, None, rest)
    } else {
        parse_param_tail_value(rest, modifier, true)?
    };
    if !ends_token(rest) {
        return None;
    }
    let (env, rest) = parse_env_binding(rest);
    if !ends_token(rest) {
        return None;
    }
    let mut notations = vec![];
    let mut rest = rest;
    if !flag {
        loop {
            let Some(r) = space1(rest) else { break };
            match parse_notation(r) {
                Some((n, r2)) => {
                    notations.push(n);
                    rest = r2;
                }
                None => break,
            }
        }
    }
    let describe = parse_describe(rest)?;
    Some(RawFlagOption {
        data: ParamData { name: name.to_string(), modifier, choice, default },
        flag,
        short: None,
        long_prefix: prefix.to_string(),
        prefixed,
        assigned,
        env,
        notations,
        describe,
    })
}
EOF"}

actions.command:
cat > /workspace/src/parser.rs <<'EOF'
// Line-level parser for argc comment tags.

#[derive(Debug, Clone, PartialEq)]
pub enum ChoiceValue {
    Values(Vec<String>),
    Fn(String, bool),
}

#[derive(Debug, Clone, PartialEq)]
pub enum DefaultValue {
    Value(String),
    Fn(String),
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Modifier {
    Optional,
    Required,
    MultipleOptional(Option<char>),
    MultipleRequired(Option<char>),
    Terminated,
}

#[derive(Debug, Clone)]
pub struct ParamData {
    pub name: String,
    pub modifier: Modifier,
    pub choice: Option<ChoiceValue>,
    pub default: Option<DefaultValue>,
}

#[derive(Debug, Clone)]
pub struct RawFlagOption {
    pub data: ParamData,
    pub flag: bool,
    pub short: Option<String>,
    pub long_prefix: String,
    pub prefixed: bool,
    pub assigned: bool,
    pub env: Option<String>, // "$$" means auto
    pub notations: Vec<String>,
    pub describe: String,
}

#[derive(Debug, Clone)]
pub struct RawPositional {
    pub data: ParamData,
    pub env: Option<String>,
    pub notation: Option<String>,
    pub describe: String,
}

#[derive(Debug, Clone)]
pub struct RawEnv {
    pub data: ParamData,
    pub describe: String,
}

#[derive(Debug, Clone)]
pub enum EventData {
    Describe(String),
    Version(String),
    Meta(String, Option<String>),
    Cmd(String),
    Aliases(Vec<String>),
    FlagOption(RawFlagOption),
    Positional(RawPositional),
    Env(RawEnv),
    Func(String),
    Unknown(String),
}

#[derive(Debug, Clone)]
pub struct Event {
    pub data: EventData,
    pub position: usize,
}

pub fn is_name_char(c: char) -> bool {
    c.is_ascii_alphanumeric() || matches!(c, '_' | '-' | '.' | ':' | '@')
}

fn is_space(c: char) -> bool {
    c == ' ' || c == '\t'
}

fn space1(s: &str) -> Option<&str> {
    let r = s.trim_start_matches(is_space);
    if r.len() == s.len() {
        None
    } else {
        Some(r)
    }
}

fn space0(s: &str) -> &str {
    s.trim_start_matches(is_space)
}

fn take_while1(s: &str, f: impl Fn(char) -> bool) -> Option<(&str, &str)> {
    let mut end = 0;
    for (i, c) in s.char_indices() {
        if f(c) {
            end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if end == 0 {
        None
    } else {
        Some((&s[..end], &s[end..]))
    }
}

fn take_while(s: &str, f: impl Fn(char) -> bool) -> (&str, &str) {
    let mut end = 0;
    for (i, c) in s.char_indices() {
        if f(c) {
            end = i + c.len_utf8();
        } else {
            break;
        }
    }
    (&s[..end], &s[end..])
}

fn ends_token(s: &str) -> bool {
    s.is_empty() || s.starts_with(is_space)
}

pub fn parse(source: &str) -> Result<Vec<Event>, String> {
    let mut result: Vec<Event> = vec![];
    let lines: Vec<&str> = source.lines().collect();
    let mut idx = 0;
    while idx < lines.len() {
        let line = lines[idx];
        let position = idx + 1;
        match parse_line(line) {
            Some(Some(mut data)) => {
                // multiline continuation
                let describable = matches!(
                    data,
                    EventData::Describe(_)
                        | EventData::Cmd(_)
                        | EventData::FlagOption(_)
                        | EventData::Positional(_)
                        | EventData::Env(_)
                );
                if describable {
                    let mut extra: Vec<String> = vec![];
                    while idx + 1 < lines.len() {
                        let next = lines[idx + 1];
                        if parse_line(next).is_some() {
                            break;
                        }
                        if let Some(text) = parse_normal_comment(next) {
                            extra.push(text.to_string());
                            idx += 1;
                        } else {
                            break;
                        }
                    }
                    if !extra.is_empty() {
                        append_describe(&mut data, &extra);
                    }
                }
                finalize_describe(&mut data);
                result.push(Event { data, position });
            }
            Some(None) => return Err(format!("syntax error at line {}", position)),
            None => {}
        }
        idx += 1;
    }
    Ok(result)
}

fn append_describe(data: &mut EventData, extra: &[String]) {
    let target: &mut String = match data {
        EventData::Describe(t) => t,
        EventData::Cmd(t) => t,
        EventData::FlagOption(p) => &mut p.describe,
        EventData::Positional(p) => &mut p.describe,
        EventData::Env(p) => &mut p.describe,
        _ => return,
    };
    for line in extra {
        target.push('\n');
        target.push_str(line);
    }
}

fn finalize_describe(data: &mut EventData) {
    let target: &mut String = match data {
        EventData::Describe(t) => t,
        EventData::Cmd(t) => t,
        EventData::FlagOption(p) => &mut p.describe,
        EventData::Positional(p) => &mut p.describe,
        EventData::Env(p) => &mut p.describe,
        _ => return,
    };
    *target = target.trim().to_string();
}

fn parse_normal_comment(line: &str) -> Option<&str> {
    let rest = line.trim_start_matches('#');
    if rest.len() == line.len() {
        return None;
    }
    let mut chars = rest.chars();
    match chars.next() {
        Some(c) if is_space(c) => Some(&rest[c.len_utf8()..]),
        _ => Some(rest),
    }
}

/// None => not a tag/fn line; Some(None) => syntax error; Some(Some(data)) => event
pub fn parse_line(line: &str) -> Option<Option<EventData>> {
    if let Some(r) = parse_tag(line) {
        return Some(r);
    }
    if let Some(name) = parse_fn(line) {
        return Some(Some(EventData::Func(name)));
    }
    None
}

fn is_fn_name_char(c: char) -> bool {
    !(c.is_whitespace()
        || matches!(
            c,
            '$' | '[' | ']' | '{' | '}' | '&' | ';' | '<' | '>' | '|' | '"' | '\'' | '`' | '\\' | '(' | ')'
        ))
}

fn parse_fn(line: &str) -> Option<String> {
    // function NAME
    if let Some(rest) = line.strip_prefix("function") {
        if let Some(rest) = space1(rest) {
            if let Some((name, _)) = take_while1(rest, is_fn_name_char) {
                return Some(name.to_string());
            }
        }
    }
    // NAME ( )
    let (name, rest) = take_while1(line, is_fn_name_char)?;
    let rest = space0(rest);
    let rest = rest.strip_prefix('(')?;
    let rest = space0(rest);
    rest.strip_prefix(')')?;
    Some(name.to_string())
}

fn parse_tag(line: &str) -> Option<Option<EventData>> {
    let rest = line.trim_start_matches('#');
    if rest.len() == line.len() {
        return None;
    }
    let rest = space0(rest);
    let rest = rest.strip_prefix('@')?;
    // text tags
    for (tag, kind) in [("describe", 0), ("version", 1), ("cmd", 2)] {
        if let Some(after) = rest.strip_prefix(tag) {
            let text = if after.is_empty() {
                Some("")
            } else {
                space1(after)
            };
            if let Some(text) = text {
                let text = text.to_string();
                let data = match kind {
                    0 => EventData::Describe(text),
                    1 => EventData::Version(text.trim().to_string()),
                    _ => EventData::Cmd(text),
                };
                return Some(Some(data));
            }
        }
    }
    // param tags
    for tag in ["flag", "option", "arg", "env"] {
        if let Some(after) = rest.strip_prefix(tag) {
            let parsed = space1(after).and_then(|input| match tag {
                "flag" => parse_flag_option_param(input, true).map(EventData::FlagOption),
                "option" => parse_flag_option_param(input, false).map(EventData::FlagOption),
                "arg" => parse_positional_param(input).map(EventData::Positional),
                _ => parse_env_param(input).map(EventData::Env),
            });
            return Some(parsed);
        }
    }
    // meta
    if let Some(after) = rest.strip_prefix("meta") {
        if let Some(input) = space1(after) {
            return Some(parse_meta(input));
        }
    }
    // alias
    if let Some(after) = rest.strip_prefix("alias") {
        if let Some(input) = space1(after) {
            if let Some(list) = parse_aliases(input) {
                return Some(Some(EventData::Aliases(list)));
            }
        }
    }
    let (name, _) = take_while(rest, |c| !c.is_whitespace());
    Some(Some(EventData::Unknown(name.to_string())))
}

fn parse_meta(input: &str) -> Option<EventData> {
    let (name, rest) = take_while1(input, is_name_char)?;
    if rest.is_empty() {
        return Some(EventData::Meta(name.to_string(), None));
    }
    let rest = space1(rest)?;
    let value = rest.trim();
    if value.is_empty() {
        Some(EventData::Meta(name.to_string(), None))
    } else {
        Some(EventData::Meta(name.to_string(), Some(value.to_string())))
    }
}

fn parse_aliases(input: &str) -> Option<Vec<String>> {
    let (first, mut rest) = take_while1(input, is_name_char)?;
    let mut list = vec![first.to_string()];
    loop {
        let Some(r) = rest.strip_prefix(',') else { break };
        let r = space0(r);
        match take_while1(r, is_name_char) {
            Some((name, r2)) => {
                list.push(name.to_string());
                rest = r2;
            }
            None => break,
        }
    }
    Some(list)
}

fn parse_modifier(input: &str, allow_multi: bool) -> (Modifier, &str) {
    let delim = |s: &str| -> (Option<char>, usize) {
        match s.chars().next() {
            Some(c) if matches!(c, ',' | ':' | ';' | '@' | '|' | '/') => (Some(c), 1),
            _ => (None, 0),
        }
    };
    if let Some(r) = input.strip_prefix('!') {
        return (Modifier::Required, r);
    }
    if allow_multi {
        if let Some(r) = input.strip_prefix('*') {
            let (d, n) = delim(r);
            return (Modifier::MultipleOptional(d), &r[n..]);
        }
        if let Some(r) = input.strip_prefix('+') {
            let (d, n) = delim(r);
            return (Modifier::MultipleRequired(d), &r[n..]);
        }
        if let Some(r) = input.strip_prefix('~') {
            return (Modifier::Terminated, r);
        }
    }
    (Modifier::Optional, input)
}

fn parse_fn_name(input: &str) -> Option<(&str, &str)> {
    let r = input.strip_prefix('`')?;
    let (name, r) = take_while1(r, is_name_char)?;
    let r = r.strip_prefix('`')?;
    Some((name, r))
}

fn parse_quoted(input: &str) -> Option<(String, &str)> {
    let q = input.chars().next()?;
    if q != '"' && q != '\'' {
        return None;
    }
    let body = &input[1..];
    let mut chars = body.char_indices();
    let mut end = None;
    while let Some((i, c)) = chars.next() {
        if c == '\\' {
            chars.next();
            continue;
        }
        if c == q {
            end = Some(i);
            break;
        }
    }
    let end = end?;
    Some((body[..end].to_string(), &body[end + 1..]))
}

fn parse_default(input: &str) -> Option<(DefaultValue, &str)> {
    let r = input.strip_prefix('=')?;
    if let Some((name, rest)) = parse_fn_name(r) {
        return Some((DefaultValue::Fn(name.to_string()), rest));
    }
    if let Some((value, rest)) = parse_quoted(r) {
        return Some((DefaultValue::Value(value), rest));
    }
    let (value, rest) = take_while(r, |c| !c.is_whitespace());
    Some((DefaultValue::Value(value.to_string()), rest))
}

fn parse_choice_value(input: &str) -> (String, &str) {
    if let Some((v, rest)) = parse_quoted(input) {
        return (v, rest);
    }
    let (v, rest) = take_while(input, |c| c != '|' && c != ']');
    (v.to_string(), rest)
}

fn parse_choice_values(input: &str) -> Option<(Vec<String>, &str)> {
    let mut values = vec![];
    let (v, mut rest) = parse_choice_value(input);
    values.push(v);
    while let Some(r) = rest.strip_prefix('|') {
        let (v, r2) = parse_choice_value(r);
        values.push(v);
        rest = r2;
    }
    Some((values, rest))
}

// returns (choice, default, rest)
fn parse_choices(input: &str) -> Option<(ChoiceValue, Option<DefaultValue>, &str)> {
    let r = input.strip_prefix('[')?;
    // choice fn
    {
        let (skip, r2) = match r.strip_prefix('?') {
            Some(r2) => (true, r2),
            None => (false, r),
        };
        if let Some((name, r3)) = parse_fn_name(r2) {
            if let Some(r4) = r3.strip_prefix(']') {
                return Some((ChoiceValue::Fn(name.to_string(), !skip), None, r4));
            }
            return None;
        }
    }
    if let Some(r2) = r.strip_prefix('=') {
        let (values, rest) = parse_choice_values(r2)?;
        if values.len() < 2 {
            return None;
        }
        let rest = rest.strip_prefix(']')?;
        let default = values[0].clone();
        return Some((ChoiceValue::Values(values), Some(DefaultValue::Value(default)), rest));
    }
    let (values, rest) = parse_choice_values(r)?;
    let rest = rest.strip_prefix(']')?;
    Some((ChoiceValue::Values(values), None, rest))
}

fn parse_param_tail_value(
    input: &str,
    modifier: Modifier,
    allow_default: bool,
) -> Option<(Option<ChoiceValue>, Option<DefaultValue>, &str)> {
    if input.starts_with('[') {
        let (c, d, rest) = parse_choices(input)?;
        return Some((Some(c), d, rest));
    }
    if allow_default && modifier == Modifier::Optional && input.starts_with('=') {
        let (d, rest) = parse_default(input)?;
        return Some((None, Some(d), rest));
    }
    Some((None, None, input))
}

fn parse_env_binding(input: &str) -> (Option<String>, &str) {
    if let Some(r) = space1(input) {
        if let Some(r2) = r.strip_prefix('$') {
            if let Some(r3) = r2.strip_prefix('$') {
                return (Some("$$".to_string()), r3);
            }
            if let Some((name, r3)) = take_while1(r2, |c| c.is_ascii_uppercase() || c == '_') {
                return (Some(name.to_string()), r3);
            }
        }
    }
    (None, input)
}

fn parse_notation(input: &str) -> Option<(String, &str)> {
    let r = input.strip_prefix('<')?;
    let (v, r) = take_while(r, |c| c != '>');
    let r = r.strip_prefix('>')?;
    if !ends_token(r) {
        return None;
    }
    Some((v.to_string(), r))
}

fn parse_describe(input: &str) -> Option<String> {
    if input.is_empty() {
        return Some(String::new());
    }
    let r = space1(input)?;
    Some(r.to_string())
}

fn parse_positional_param(input: &str) -> Option<RawPositional> {
    let (name, rest) = take_while1(input, is_name_char)?;
    let (modifier, rest) = parse_modifier(rest, true);
    let (choice, default, rest) = parse_param_tail_value(rest, modifier, true)?;
    if !ends_token(rest) {
        return None;
    }
    let (env, rest) = parse_env_binding(rest);
    if !ends_token(rest) {
        return None;
    }
    let mut notation = None;
    let mut rest = rest;
    if let Some(r) = space1(rest) {
        if let Some((n, r2)) = parse_notation(r) {
            notation = Some(n);
            rest = r2;
        }
    }
    let describe = parse_describe(rest)?;
    Some(RawPositional {
        data: ParamData { name: name.to_string(), modifier, choice, default },
        env,
        notation,
        describe,
    })
}

fn parse_env_param(input: &str) -> Option<RawEnv> {
    let (name, rest) = take_while1(input, is_name_char)?;
    let (modifier, rest) = parse_modifier(rest, true);
    let (choice, default, rest) = parse_param_tail_value(rest, modifier, true)?;
    let describe = parse_describe(rest)?;
    Some(RawEnv {
        data: ParamData { name: name.to_string(), modifier, choice, default },
        describe,
    })
}

fn parse_short(input: &str) -> Option<(String, &str)> {
    let mut chars = input.chars();
    let p = chars.next()?;
    if p != '-' && p != '+' {
        return None;
    }
    let c = chars.next()?;
    if !is_name_char(c) || c == '-' {
        return None;
    }
    let rest = &input[1 + c.len_utf8()..];
    let rest = space1(rest)?;
    Some((format!("{}{}", p, c), rest))
}

fn parse_flag_option_param(input: &str, flag: bool) -> Option<RawFlagOption> {
    if let Some((short, rest)) = parse_short(input) {
        if let Some(mut p) = parse_long_part(rest, flag) {
            p.short = Some(short);
            return Some(p);
        }
    }
    parse_long_part(input, flag)
}

fn parse_long_part(input: &str, flag: bool) -> Option<RawFlagOption> {
    let (prefix, rest) = if let Some(r) = input.strip_prefix("--") {
        ("--", r)
    } else if let Some(r) = input.strip_prefix('-') {
        ("-", r)
    } else if let Some(r) = input.strip_prefix('+') {
        ("+", r)
    } else {
        return None;
    };
    let (mut name, rest) = take_while(rest, is_name_char);
    if name.is_empty() {
        return None;
    }
    let mut prefixed = false;
    let mut assigned = false;
    if name.ends_with('-') {
        prefixed = true;
        name = &name[..name.len() - 1];
    } else if name.ends_with(':') {
        assigned = true;
        name = &name[..name.len() - 1];
    }
    if name.is_empty() && prefix != "-" {
        return None;
    }
    let (modifier, rest) = if flag {
        match rest.strip_prefix('*') {
            Some(r) => (Modifier::MultipleOptional(None), r),
            None => (Modifier::Optional, rest),
        }
    } else {
        parse_modifier(rest, true)
    };
    let (choice, default, rest) = if flag {
        (None, None, rest)
    } else {
        parse_param_tail_value(rest, modifier, true)?
    };
    if !ends_token(rest) {
        return None;
    }
    let (env, rest) = parse_env_binding(rest);
    if !ends_token(rest) {
        return None;
    }
    let mut notations = vec![];
    let mut rest = rest;
    if !flag {
        loop {
            let Some(r) = space1(rest) else { break };
            match parse_notation(r) {
                Some((n, r2)) => {
                    notations.push(n);
                    rest = r2;
                }
                None => break,
            }
        }
    }
    let describe = parse_describe(rest)?;
    Some(RawFlagOption {
        data: ParamData { name: name.to_string(), modifier, choice, default },
        flag,
        short: None,
        long_prefix: prefix.to_string(),
        prefixed,
        assigned,
        env,
        notations,
        describe,
    })
}
