use crate::parser::{ChoiceValue, DefaultValue, Modifier, RawEnv, RawFlagOption, RawPositional};

pub const MAX_ARGS: usize = 32767;

pub fn to_notation(name: &str) -> String {
    name.to_uppercase().replace('_', "-")
}

pub fn to_env_name(name: &str) -> String {
