        .map(|c| if c.is_ascii_alphanumeric() || c == '_' { c } else { '_' })
        .collect()
}

#[derive(Debug, Clone)]
pub struct FlagOptionParam {
    pub id: String,
    pub name: String,
    pub describe: String,
    pub short: Option<String>,
    pub long_prefix: String,
    pub flag: bool,
