    pub describe: String,
    pub required: bool,
    pub default: Option<DefaultValue>,
    pub choice: Option<ChoiceValue>,
    pub inherited: bool,
    pub position: usize,
}

fn notation_range(n: &str) -> (usize, usize) {
    if n.ends_with('*') {
        (0, MAX_ARGS)
    } else if n.ends_with('+') {
        (1, MAX_ARGS)
    } else if n.ends_with('?') {
        (0, 1)
    } else {
        (1, 1)
    }
}

impl FlagOptionParam {
    pub fn from_raw(raw: RawFlagOption, position: usize) -> Result<Self, String> {
        let name = raw.data.name.clone();
        let id = if raw.long_prefix == "+" {
            format!("plus_{}", name)
        } else {
            name.clone()
        };
        let modifier = raw.data.modifier;
        let multiple_occurs = matches!(modifier, Modifier::MultipleOptional(_) | Modifier::MultipleRequired(_));
        let terminated = modifier == Modifier::Terminated;
        let delimiter = match modifier {
            Modifier::MultipleOptional(d) | Modifier::MultipleRequired(d) => d,
            _ => None,
        };
        let required = matches!(modifier, Modifier::Required | Modifier::MultipleRequired(_)) && raw.data.default.is_none();
        let env = raw.env.map(|e| if e == "$$" { to_env_name(&name) } else { e });
        let tag = if raw.flag { "@flag" } else { "@option" };
        let (notations, num_args, multiple_values) = if raw.flag {
            (vec![], (0, 0), multiple_occurs)
        } else {
            let mut notations: Vec<String> = if raw.notations.is_empty() {
                vec![to_notation(&name)]
            } else {
                raw.notations.iter().map(|v| to_notation(v)).collect()
            };
            if terminated {
                if let Some(last) = notations.last_mut() {
                    last.push('~');
                }
            }
            let count = notations.len();
            let (lmin, lmax) = if raw.notations.is_empty() {
                (1, 1)
            } else {
                notation_range(&to_notation(raw.notations.last().unwrap()))
            };
