            if terminated {
                max = MAX_ARGS;
            }
            let multiple_values = multiple_occurs || max > 1;
            if count > 1 {
                if delimiter.is_some() {
                    return Err(format!(
                        "{}(line {}) is invalid, cannot combine delmiter and multiple notations",
                        tag, position
                    ));
                }
                if raw.assigned {
                    return Err(format!(
                        "{}(line {}) is invalid, cannot combine assign and multiple notations",
                        tag, position
                    ));
                }
            }
            (notations, (min, max), multiple_values)
        };
        Ok(FlagOptionParam {
            id,
            name,
            describe: raw.describe,
            short: raw.short,
            long_prefix: raw.long_prefix,
            flag: raw.flag,
            notations,
            raw_notations: raw.notations,
            required,
            multiple_values,
            multiple_occurs,
            num_args,
            delimiter,
            terminated,
            prefixed: raw.prefixed,
            assigned: raw.assigned,
            default: raw.data.default,
            choice: raw.data.choice,
            env,
            inherited: false,
            position,
            is_help: false,
            is_version: false,
        })
    }

    pub fn new_flag(name: &str, long_prefix: &str, short: Option<&str>, describe: &str) -> Self {
        FlagOptionParam {
            id: name.to_string(),
            name: name.to_string(),
            describe: describe.to_string(),
            short: short.map(|v| v.to_string()),
            long_prefix: long_prefix.to_string(),
            flag: true,
            notations: vec![],
            raw_notations: vec![],
            required: false,
            multiple_values: false,
            multiple_occurs: false,
            num_args: (0, 0),
            delimiter: None,
            terminated: false,
            prefixed: false,
            assigned: false,
            default: None,
            choice: None,
            env: None,
            inherited: false,
            position: 0,
            is_help: false,
            is_version: false,
        }
    }

    pub fn long_name(&self) -> String {
        format!("{}{}", self.long_prefix, self.name)
    }

    pub fn var_name(&self) -> String {
        format!("argc_{}", sanitize_var_name(&self.id))
    }

    pub fn is_single_long(&self) -> bool {
        self.long_prefix.len() == 1 && self.name.chars().count() == 1
    }

    pub fn render_notations(&self) -> String {
        if self.flag {
            return if self.multiple_occurs { "...".to_string() } else { String::new() };
        }
        let sep = if self.assigned { "=" } else { " " };
        if self.notations.len() == 1 {
            let n = &self.notations[0];
            if self.multiple_occurs {
                if self.required {
                    format!("{}<{}>...", sep, n)
                } else {
                    format!("{}[{}]...", sep, n)
                }
            } else {
                format!("{}<{}>", sep, n)
            }
        } else {
            let list: Vec<String> = self.notations.iter().map(|n| format!("<{}>", n)).collect();
            format!("{}{}", sep, list.join(" "))
        }
    }

    pub fn render_name_notations(&self) -> String {
        let mut out = String::new();
        if let Some(short) = &self.short {
            out.push_str(short);
            out.push_str(", ");
        } else if self.is_single_long() {
            out.push_str(&self.long_name());
            out.push_str(&self.render_notations());
            return out;
        } else {
            out.push_str("    ");
        }
        if self.long_prefix.len() == 1 {
            out.push(' ');
        }
        out.push_str(&self.long_name());
        out.push_str(&self.render_notations());
        out
    }

    pub fn render_usage(&self) -> String {
        format!("{}{}", self.long_name(), self.render_notations())
    }

    // used in error messages: `--tries <NUM>`
    pub fn render_long_name_notations(&self) -> String {
        format!("{}{}", self.long_name(), self.render_notations())
    }

    pub fn render_first_notation(&self) -> String {
        format!("<{}>", self.notations.first().cloned().unwrap_or_default())
    }

    pub fn list_names(&self) -> Vec<String> {
        let mut v = vec![self.long_name()];
        if let Some(s) = &self.short {
            v.push(s.clone());
        }
        v
    }

    pub fn is_option(&self) -> bool {
        !self.flag
    }
}

impl PositionalParam {
    pub fn from_raw(raw: RawPositional, position: usize) -> Self {
        let name = raw.data.name.clone();
        let modifier = raw.data.modifier;
        let multiple = matches!(
            modifier,
            Modifier::MultipleOptional(_) | Modifier::MultipleRequired(_) | Modifier::Terminated
        );
        let terminated = modifier == Modifier::Terminated;
        let delimiter = match modifier {
            Modifier::MultipleOptional(d) | Modifier::MultipleRequired(d) => d,
            _ => None,
        };
        let required = matches!(modifier, Modifier::Required | Modifier::MultipleRequired(_)) && raw.data.default.is_none();
        let env = raw.env.map(|e| if e == "$$" { to_env_name(&name) } else { e });
        let notation = match raw.notation {
            Some(n) => to_notation(&n),
            None => to_notation(&name),
        };
        PositionalParam {
            id: name,
            describe: raw.describe,
            notation,
            required,
            multiple,
            delimiter,
            terminated,
            default: raw.data.default,
            choice: raw.data.choice,
            env,
            position,
        }
    }

    pub fn var_name(&self) -> String {
        format!("argc_{}", sanitize_var_name(&self.id))
    }

    pub fn render_notation(&self) -> String {
        let mut s = if self.required {
            format!("<{}>", self.notation)
        } else {
            format!("[{}]", self.notation)
        };
        if self.multiple {
            s.push_str("...");
        }
        s
    }
}

impl EnvParam {
    pub fn from_raw(raw: RawEnv, position: usize) -> Result<Self, String> {
        let modifier = raw.data.modifier;
        if !matches!(modifier, Modifier::Optional | Modifier::Required) {
            return Err(format!("@env(line {}) is invalid, can only be a single value", position));
        }
        let required = modifier == Modifier::Required && raw.data.default.is_none();
        Ok(EnvParam {
            id: raw.data.name,
            describe: raw.describe,
            required,
            default: raw.data.default,
            choice: raw.data.choice,
            inherited: false,
            position,
        })
    }

    pub fn render_name(&self) -> String {
        if self.required {
            format!("{}*", self.id)
        } else {
            self.id.clone()
        }
    }
}

/// Render the describe text with extra info ([possible values], [default], [env])
pub fn render_describe(
    describe: &str,
    default: &Option<DefaultValue>,
    choice: &Option<ChoiceValue>,
    env: &Option<String>,
) -> String {
    let mut extras: Vec<String> = vec![];
    let mut show_default = true;
    if let Some(ChoiceValue::Values(values)) = choice {
        let documented = values.iter().all(|v| describe.contains(v.as_str()));
        if documented {
            show_default = false;
        } else {
            extras.push(format!("[possible values: {}]", values.join(", ")));
        }
    }
    if show_default {
        if let Some(DefaultValue::Value(v)) = default {
            extras.push(format!("[default: {}]", v));
        }
    }
    if let Some(e) = env {
        extras.push(format!("[env: {}]", e));
    }
    if extras.is_empty() {
        return describe.to_string();
    }
    let mut out = describe.to_string();
    let multiline = describe.contains('\n');
    for (i, e) in extras.iter().enumerate() {
        if out.is_empty() && i == 0 {
            out.push_str(e);
        } else if multiline {
            out.push('\n');
            out.push_str(e);
        } else {
            out.push(' ');
            out.push_str(e);
        }
    }
    out
}
EOF"}

