use crate::param::*;
use crate::parser::{parse, ChoiceValue, DefaultValue, Event, EventData};
use std::collections::HashMap;

#[derive(Debug, Clone, Default)]
pub struct Command {
    pub name: Option<String>,
    pub fn_name: Option<String>,
    pub describe: String,
    pub version: Option<String>,
    pub aliases: Vec<(String, usize)>,
    pub flag_options: Vec<FlagOptionParam>,
    pub positionals: Vec<PositionalParam>,
    pub envs: Vec<EnvParam>,
    pub subcommands: Vec<Command>,
    pub paths: Vec<String>,
    pub metadata: Vec<(String, Option<String>)>,
    pub command_fn: Option<String>,
    pub default_subcommand: bool,
    pub dotenv: Option<String>,
    pub require_tools: Vec<String>,
    pub combine_shorts: bool,
    pub inherit_flag_options: bool,
    pub symbols: Vec<(char, String, Option<String>)>,
    pub before_hook: Option<String>,
    pub after_hook: Option<String>,
    pub position: usize,
    pub fn_position: usize,
    pub root_name: String,
    pub is_root: bool,
}

#[derive(PartialEq)]
enum Scope {
    Root,
    CmdStart,
    FnEnd,
}

impl Command {
    pub fn new(source: &str, root_name: &str) -> Result<Command, String> {
        let events = parse(source)?;
        let mut root = Command {
            name: Some(root_name.to_string()),
            root_name: root_name.to_string(),
            is_root: true,
            ..Default::default()
        };
        let mut scope = Scope::Root;
        let mut pending: Option<Command> = None;
        let mut functions: Vec<(String, usize)> = vec![];
        // fn name -> path indexes
        let mut fn_paths: HashMap<String, Vec<usize>> = HashMap::new();
        let mut cmd_pos = 0;
        // names registry per parent path: name -> position
        let mut names_registry: HashMap<Vec<usize>, Vec<(String, usize)>> = HashMap::new();

        for event in events.iter() {
            let Event { data, position } = event.clone();
            let position = position;
            macro_rules! get_cmd {
                ($tag:expr) => {{
                    if scope == Scope::FnEnd {
                        return Err(format!(
                            "{}(line {}) shouldn't be here, @cmd is missing?",
                            $tag, position
                        ));
                    }
                    match pending.as_mut() {
                        Some(c) => c,
                        None => &mut root,
                    }
                }};
            }
            match data {
                EventData::Describe(text) => {
                    let cmd = get_cmd!("@describe");
                    cmd.describe = text;
                }
                EventData::Version(text) => {
                    let cmd = get_cmd!("@version");
                    cmd.version = Some(text);
                }
                EventData::Meta(key, value) => {
                    let cmd = get_cmd!("@meta");
                    match key.as_str() {
                        "version" => {
                            cmd.version = Some(value.clone().unwrap_or_default());
                        }
                        "dotenv" => {
                            cmd.dotenv = Some(value.clone().unwrap_or_else(|| ".env".to_string()));
                        }
                        "default-subcommand" => {
                            cmd.default_subcommand = true;
                        }
                        "require-tools" => {
                            let v = value.clone().unwrap_or_default();
                            cmd.require_tools = v
                                .split(',')
                                .map(|s| s.trim().to_string())
                                .filter(|s| !s.is_empty())
                                .collect();
                        }
                        "combine-shorts" => {
                            cmd.combine_shorts = true;
                        }
                        "inherit-flag-options" => {
                            cmd.inherit_flag_options = true;
                        }
                        "symbol" => {
                            let v = value.clone().unwrap_or_default();
                            match parse_symbol(&v) {
                                Some(sym) => cmd.symbols.push(sym),
                                None => {
                                    return Err(format!("@meta(line {}) invalid symbol value", position))
                                }
                            }
                        }
                        _ => {}
                    }
                    if let Some(item) = cmd.metadata.iter_mut().find(|(k, _)| *k == key) {
                        item.1 = value;
                    } else {
                        cmd.metadata.push((key, value));
                    }
                }
                EventData::Cmd(text) => {
                    if scope == Scope::CmdStart {
                        return Err(format!("@cmd(line {}) missing function?", cmd_pos));
                    }
                    if let Some(p) = pending.take() {
                        root.subcommands.push(p);
                    }
                    let sub = Command {
                        describe: text,
                        position,
                        root_name: root_name.to_string(),
                        ..Default::default()
                    };
                    pending = Some(sub);
                    cmd_pos = position;
                    scope = Scope::CmdStart;
                }
                EventData::Aliases(list) => {
                    let cmd = get_cmd!("@alias");
                    for a in list {
                        cmd.aliases.push((a, position));
                    }
                }
                EventData::FlagOption(raw) => {
                    let tag = if raw.flag { "@flag" } else { "@option" };
                    let cmd = get_cmd!(tag);
                    let param = FlagOptionParam::from_raw(raw, position)?;
                    for name in param.list_names() {
                        if let Some(exist) = cmd
                            .flag_options
                            .iter()
                            .find(|p| p.list_names().contains(&name))
                        {
                            return Err(format!(
                                "{}(line {}) has '{}' already exists at line {}",
                                tag, position, name, exist.position
                            ));
                        }
                    }
                    cmd.flag_options.push(param);
                }
                EventData::Positional(raw) => {
                    let cmd = get_cmd!("@arg");
                    let param = PositionalParam::from_raw(raw, position);
                    if let Some(exist) = cmd.positionals.iter().find(|p| p.id == param.id) {
                        return Err(format!(
                            "@arg(line {}) has '{}' already exists at line {}",
                            position, param.id, exist.position
                        ));
                    }
                    cmd.positionals.push(param);
                }
                EventData::Env(raw) => {
                    let cmd = get_cmd!("@env");
                    let param = EnvParam::from_raw(raw, position)?;
                    if let Some(exist) = cmd.envs.iter().find(|p| p.id == param.id) {
                        return Err(format!(
                            "@env(line {}) has '{}' already exists at line {}",
                            position, param.id, exist.position
                        ));
                    }
                    cmd.envs.push(param);
                }
                EventData::Func(name) => {
                    functions.push((name.clone(), position));
                    if name == "_argc_before" {
                        root.before_hook = Some(name.clone());
                    } else if name == "_argc_after" {
                        root.after_hook = Some(name.clone());
                    }
                    if scope == Scope::CmdStart {
                        let mut sub = pending.take().unwrap();
                        let parts: Vec<&str> = name.split("::").collect();
                        let (parent_path, cmd_name) = if parts.len() > 1 {
                            let parent_fn = parts[..parts.len() - 1].join("::");
                            match fn_paths.get(&parent_fn) {
                                Some(p) => (p.clone(), parts[parts.len() - 1].to_string()),
                                None => {
                                    return Err(format!(
                                        "{}(line {}) lack of parent command",
                                        name, position
                                    ));
                                }
                            }
                        } else {
                            (vec![], name.clone())
                        };
                        sub.name = Some(cmd_name.clone());
                        sub.fn_name = Some(name.clone());
                        sub.fn_position = position;
                        if cmd_name.contains('_') {
                            sub.aliases.insert(0, (cmd_name.replace('_', "-"), 0));
                        }
                        // conflicts
                        let registry = names_registry.entry(parent_path.clone()).or_default();
                        if let Some((_, p)) = registry.iter().find(|(n, _)| *n == cmd_name) {
                            return Err(format!(
                                "{}(line {}) conflicts with cmd or alias at line {}",
                                cmd_name, position, p
                            ));
                        }
                        for (alias, apos) in sub.aliases.iter() {
                            if *apos == 0 {
                                continue;
                            }
                            if let Some((_, p)) = registry.iter().find(|(n, _)| n == alias) {
                                return Err(format!(
                                    "@alias(line {}) conflicts with cmd or alias at line {}",
                                    apos, p
                                ));
                            }
                        }
                        registry.push((cmd_name.clone(), position));
                        for (alias, apos) in sub.aliases.iter() {
                            if *apos == 0 {
                                continue;
                            }
                            registry.push((alias.clone(), *apos));
                        }
                        // attach
                        let parent = get_by_path(&mut root, &parent_path);
                        parent.subcommands.push(sub);
                        let mut path = parent_path.clone();
                        path.push(parent.subcommands.len() - 1);
                        fn_paths.insert(name.clone(), path);
                    }
                    scope = Scope::FnEnd;
                }
                EventData::Unknown(name) => {
                    return Err(format!("@{}(line {}) is unknown tag", name, position));
                }
            }
        }
        if let Some(p) = pending.take() {
            root.subcommands.push(p);
        }

        // check missing functions
        let fn_names: Vec<&str> = functions.iter().map(|(n, _)| n.as_str()).collect();
        check_missing(&root, &fn_names)?;

        // command fns
        let has_main = fn_names.contains(&"main");
        if has_main {
            root.command_fn = Some("main".to_string());
        }
        set_command_fns(&mut root, &fn_names);

        // paths
        let rn = root_name.to_string();
        set_paths(&mut root, vec![]);
        let _ = rn;

        // help/version flags and inheritance
        let inherit = root.inherit_flag_options;
        finalize(&mut root, true, &[], &[], inherit);
        Ok(root)
    }

    pub fn cmd_name(&self) -> String {
        self.name.clone().unwrap_or_else(|| self.root_name.clone())
    }

    pub fn full_name(&self) -> String {
        let mut v = vec![self.root_name.clone()];
        v.extend(self.paths.iter().cloned());
        v.join("-")
    }

    pub fn usage_name(&self) -> String {
        let mut v = vec![self.root_name.clone()];
        v.extend(self.paths.iter().cloned());
        v.join(" ")
    }

    pub fn alias_names(&self) -> Vec<String> {
        self.aliases.iter().map(|(a, _)| a.clone()).collect()
    }

    pub fn find_subcommand(&self, name: &str) -> Option<&Command> {
        self.subcommands.iter().find(|c| {
            c.name.as_deref() == Some(name) || c.aliases.iter().any(|(a, _)| a == name)
        })
    }

    pub fn find_subcommand_index(&self, name: &str) -> Option<usize> {
        self.subcommands.iter().position(|c| {
            c.name.as_deref() == Some(name) || c.aliases.iter().any(|(a, _)| a == name)
        })
    }

    pub fn find_default_subcommand(&self) -> Option<&Command> {
        self.subcommands.iter().find(|c| c.default_subcommand)
    }

    pub fn list_subcommand_names(&self) -> Vec<String> {
        let mut out = vec![];
        for sub in &self.subcommands {
            out.push(sub.cmd_name());
            for (a, _) in &sub.aliases {
                out.push(a.clone());
            }
        }
        out
    }

    pub fn find_flag_option(&self, name: &str) -> Option<&FlagOptionParam> {
        self.flag_options.iter().find(|p| p.long_name() == name || p.short.as_deref() == Some(name))
    }

    pub fn user_flag_options(&self) -> impl Iterator<Item = &FlagOptionParam> {
        self.flag_options.iter().filter(|p| !p.is_help && !p.is_version)
    }

    pub fn exist_version(&self) -> bool {
        self.version.is_some()
    }

    pub fn delegated(&self) -> bool {
        self.subcommands.is_empty()
            && self.flag_options.iter().all(|p| p.is_help || p.is_version)
            && self.positionals.len() == 1
            && self.positionals[0].terminated
    }

    pub fn no_flags_options_subcommands(&self) -> bool {
        self.subcommands.is_empty() && self.flag_options.iter().all(|p| p.is_help || p.is_version)
    }
}

pub fn get_by_path<'a>(root: &'a mut Command, path: &[usize]) -> &'a mut Command {
    let mut cmd = root;
    for i in path {
        cmd = &mut cmd.subcommands[*i];
    }
    cmd
}

fn parse_symbol(v: &str) -> Option<(char, String, Option<String>)> {
    let mut chars = v.chars();
    let c = chars.next()?;
    if c.is_ascii_alphanumeric() || c == '-' {
        return None;
    }
    let rest = &v[c.len_utf8()..];
    let end = rest.find(|ch: char| !crate::parser::is_name_char(ch)).unwrap_or(rest.len());
    let name = &rest[..end];
    if name.is_empty() {
        return None;
    }
    let tail = &rest[end..];
    if tail.is_empty() {
        return Some((c, name.to_string(), None));
    }
    let t = tail.strip_prefix("[`")?;
    let fend = t.find('`')?;
    let fname = &t[..fend];
    if fname.is_empty() || !fname.chars().all(crate::parser::is_name_char) {
        return None;
    }
    if &t[fend..] != "`]" {
        return None;
    }
    Some((c, name.to_string(), Some(fname.to_string())))
}

fn check_fn(name: &str, position: usize, fns: &[&str]) -> Result<(), String> {
    if fns.contains(&name) {
        Ok(())
    } else {
        Err(format!("{}(line {}) is missing", name, position))
    }
}

fn check_param_fns(
    default: &Option<DefaultValue>,
    choice: &Option<ChoiceValue>,
    position: usize,
    fns: &[&str],
) -> Result<(), String> {
    if let Some(ChoiceValue::Fn(f, _)) = choice {
        check_fn(f, position, fns)?;
    }
    if let Some(DefaultValue::Fn(f)) = default {
        check_fn(f, position, fns)?;
    }
    Ok(())
}

fn check_missing(cmd: &Command, fns: &[&str]) -> Result<(), String> {
    let mut items: Vec<(usize, Option<DefaultValue>, Option<ChoiceValue>)> = vec![];
    for p in &cmd.flag_options {
        items.push((p.position, p.default.clone(), p.choice.clone()));
    }
    for p in &cmd.positionals {
        items.push((p.position, p.default.clone(), p.choice.clone()));
    }
    for p in &cmd.envs {
        items.push((p.position, p.default.clone(), p.choice.clone()));
    }
    items.sort_by_key(|v| v.0);
    for (pos, d, c) in items {
        check_param_fns(&d, &c, pos, fns)?;
    }
    for sub in &cmd.subcommands {
        check_missing(sub, fns)?;
    }
    Ok(())
}

fn set_command_fns(cmd: &mut Command, fns: &[&str]) {
    for sub in cmd.subcommands.iter_mut() {
        if let Some(fn_name) = sub.fn_name.clone() {
            if sub.subcommands.is_empty() {
                sub.command_fn = Some(fn_name);
            } else {
                let main = format!("{}::main", fn_name);
                if fns.contains(&main.as_str()) {
                    sub.command_fn = Some(main);
                }
            }
        }
        set_command_fns(sub, fns);
    }
}

fn set_paths(cmd: &mut Command, paths: Vec<String>) {
    cmd.paths = paths.clone();
    for sub in cmd.subcommands.iter_mut() {
        let mut p = paths.clone();
        p.push(sub.cmd_name());
        set_paths(sub, p);
    }
}

fn finalize(
    cmd: &mut Command,
    is_root: bool,
    parent_flags: &[FlagOptionParam],
    parent_envs: &[EnvParam],
    inherit_flags: bool,
) {
    // help / version
    let any_describe = cmd.flag_options.iter().any(|p| !p.describe.is_empty());
    let single = cmd.flag_options.iter().any(|p| p.long_prefix.len() == 1);
    let long_prefix = if single { "-" } else { "--" };
    let used = |name: &str, cmd: &Command| cmd.flag_options.iter().any(|p| p.list_names().iter().any(|n| n == name));
    if !cmd.flag_options.iter().any(|p| p.id == "help") {
        let short = if used("-h", cmd) { None } else { Some("-h") };
        let mut f = FlagOptionParam::new_flag(
            "help",
            long_prefix,
            short,
            if any_describe { "Print help" } else { "" },
        );
        f.is_help = true;
        cmd.flag_options.push(f);
    } else {
        for p in cmd.flag_options.iter_mut() {
            if p.id == "help" && p.flag {
                p.is_help = true;
            }
        }
    }
    if is_root || cmd.version.is_some() {
        if !cmd.flag_options.iter().any(|p| p.id == "version") {
            let short = if used("-V", cmd) { None } else { Some("-V") };
            let mut f = FlagOptionParam::new_flag(
                "version",
                long_prefix,
                short,
                if any_describe { "Print version" } else { "" },
            );
            f.is_version = true;
            cmd.flag_options.push(f);
        } else {
            for p in cmd.flag_options.iter_mut() {
                if p.id == "version" && p.flag {
                    p.is_version = true;
                }
            }
        }
    }
    // inherit flags
    if !is_root && inherit_flags {
        let mut inherited: Vec<FlagOptionParam> = vec![];
        for pf in parent_flags {
            if cmd.flag_options.iter().any(|p| p.id == pf.id) {
                continue;
            }
            let mut f = pf.clone();
            f.inherited = true;
            inherited.push(f);
        }
        if !inherited.is_empty() {
            inherited.extend(cmd.flag_options.drain(..));
            cmd.flag_options = inherited;
        }
    }
    // inherit envs
    if !is_root {
        let mut inherited: Vec<EnvParam> = vec![];
        for pe in parent_envs {
            if cmd.envs.iter().any(|p| p.id == pe.id) {
                continue;
            }
            let mut e = pe.clone();
            e.inherited = true;
            inherited.push(e);
        }
        if !inherited.is_empty() {
            inherited.extend(cmd.envs.drain(..));
            cmd.envs = inherited;
        }
    }
    let my_flags: Vec<FlagOptionParam> = cmd
        .flag_options
        .iter()
        .filter(|p| !p.is_help && !p.is_version)
        .cloned()
        .collect();
    let my_envs = cmd.envs.clone();
    for sub in cmd.subcommands.iter_mut() {
        finalize(sub, false, &my_flags, &my_envs, inherit_flags);
    }
}
EOF"}

