use crate::command::Command;
use crate::json::Json;
use crate::param::*;
use crate::parser::{ChoiceValue, DefaultValue};

fn default_json(d: &Option<DefaultValue>) -> Json {
    match d {
        None => Json::Null,
        Some(DefaultValue::Value(v)) => Json::Obj(vec![
            ("type".into(), Json::str("Value")),
            ("value".into(), Json::str(v)),
        ]),
        Some(DefaultValue::Fn(v)) => Json::Obj(vec![
            ("type".into(), Json::str("Fn")),
            ("value".into(), Json::str(v)),
        ]),
    }
}

fn choice_json(c: &Option<ChoiceValue>) -> Json {
    match c {
        None => Json::Null,
        Some(ChoiceValue::Values(vs)) => Json::Obj(vec![
            ("type".into(), Json::str("Values")),
            ("data".into(), Json::Arr(vs.iter().map(|v| Json::str(v)).collect())),
        ]),
        Some(ChoiceValue::Fn(f, validate)) => Json::Obj(vec![
            ("type".into(), Json::str("Fn")),
            ("data".into(), Json::Arr(vec![Json::str(f), Json::Bool(*validate)])),
        ]),
    }
}

fn delim_json(d: &Option<char>) -> Json {
    match d {
        Some(c) => Json::Str(c.to_string()),
        None => Json::Null,
    }
}

fn flag_option_json(p: &FlagOptionParam) -> Json {
    Json::Obj(vec![
        ("id".into(), Json::str(&p.id)),
        ("long_name".into(), Json::str(&p.long_name())),
        ("short_name".into(), Json::opt_str(&p.short)),
        ("describe".into(), Json::str(&p.describe)),
        ("flag".into(), Json::Bool(p.flag)),
        ("notations".into(), Json::Arr(p.notations.iter().map(|v| Json::str(v)).collect())),
        ("required".into(), Json::Bool(p.required)),
        ("multiple_values".into(), Json::Bool(p.multiple_values)),
        ("multiple_occurs".into(), Json::Bool(p.multiple_occurs)),
        (
            "num_args".into(),
            Json::Arr(vec![Json::Num(p.num_args.0 as i64), Json::Num(p.num_args.1 as i64)]),
        ),
        ("delimiter".into(), delim_json(&p.delimiter)),
        ("terminated".into(), Json::Bool(p.terminated)),
        ("prefixed".into(), Json::Bool(p.prefixed)),
        ("assigned".into(), Json::Bool(p.assigned)),
        ("default".into(), default_json(&p.default)),
        ("choice".into(), choice_json(&p.choice)),
        ("env".into(), Json::opt_str(&p.env)),
        ("inherited".into(), Json::Bool(p.inherited)),
    ])
}

fn positional_json(p: &PositionalParam) -> Json {
    Json::Obj(vec![
        ("id".into(), Json::str(&p.id)),
        ("describe".into(), Json::str(&p.describe)),
        ("notation".into(), Json::str(&p.notation)),
        ("required".into(), Json::Bool(p.required)),
        ("multiple".into(), Json::Bool(p.multiple)),
        ("delimiter".into(), delim_json(&p.delimiter)),
        ("terminated".into(), Json::Bool(p.terminated)),
        ("default".into(), default_json(&p.default)),
        ("choice".into(), choice_json(&p.choice)),
        ("env".into(), Json::opt_str(&p.env)),
    ])
}

fn env_json(p: &EnvParam) -> Json {
    Json::Obj(vec![
        ("id".into(), Json::str(&p.id)),
        ("describe".into(), Json::str(&p.describe)),
        ("required".into(), Json::Bool(p.required)),
        ("default".into(), default_json(&p.default)),
        ("choice".into(), choice_json(&p.choice)),
        ("inherited".into(), Json::Bool(p.inherited)),
    ])
}

pub fn command_json(cmd: &Command) -> Json {
