    pub fn new(msg: impl Into<String>) -> Self {
        AppError { msg: msg.into(), cause: None }
    }
    pub fn debug_fmt(&self) -> String {
        match &self.cause {
            Some(c) => format!("{}\n\nCaused by:\n    {}", self.msg, c),
            None => self.msg.clone(),
        }
    }
}

impl From<String> for AppError {
    fn from(s: String) -> Self {
        AppError::new(s)
    }
}

fn io_error_string(err: &std::io::Error) -> String {
    let s = err.to_string();
    s
}

pub fn read_script(path: &str) -> Result<String, AppError> {
    match std::fs::read(path) {
        Ok(bytes) => Ok(String::from_utf8_lossy(&bytes).to_string()),
        Err(err) => Err(AppError {
            msg: format!("Failed to load script at '{}'", path),
            cause: Some(io_error_string(&err)),
        }),
    }
}

pub fn script_name(path: &str) -> String {
    Path::new(path)
