                println!("argc {}", env!("CARGO_PKG_VERSION"));
                Ok(0)
            }
            _ => Err(AppError::new(format!("Unknown option `{}`", action))),
        }
    } else {
        Err(AppError::new("Argcfile not found, try `argc --argc-help` for help."))
    }
}

fn main() {
    match run() {
        Ok(code) => exit(code),
        Err(err) => {
            eprintln!("{}", err.debug_fmt());
            exit(1);
        }
    }
}
