pub fn escape_shell_words(value: &str) -> String {
    if value.is_empty() {
        return "''".to_string();
    }
    let needs = value.chars().any(|c| {
        matches!(
            c,
            '|' | '&' | ';' | '<' | '>' | '(' | ')' | '$' | '`' | '\\' | '"' | '\'' | ' ' | '\t' | '\r' | '\n'
                | '*' | '?' | '[' | '#' | '~' | '=' | '%'
        )
    });
    if !needs {
        return value.to_string();
    }
    let mut out = String::with_capacity(value.len() + 2);
    out.push('\'');
    for c in value.chars() {
        if c == '\'' {
            out.push_str("'\\''");
        } else {
            out.push(c);
        }
    }
    out.push('\'');
    out
}

const B64: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

pub fn base64_encode(data: &[u8]) -> String {
    let mut out = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(B64[((n >> 18) & 63) as usize] as char);
        out.push(B64[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            out.push(B64[((n >> 6) & 63) as usize] as char);
        } else {
            out.push('=');
        }
        if chunk.len() > 2 {
            out.push(B64[(n & 63) as usize] as char);
        } else {
            out.push('=');
        }
    }
    out
}

#[allow(dead_code)]
pub fn base64_decode(data: &str) -> Option<Vec<u8>> {
    let mut out = vec![];
    let mut buf = 0u32;
    let mut bits = 0;
    for c in data.bytes() {
        if c == b'=' {
            break;
        }
        let v = B64.iter().position(|&b| b == c)? as u32;
        buf = (buf << 6) | v;
        bits += 6;
        if bits >= 8 {
            bits -= 8;
            out.push(((buf >> bits) & 0xff) as u8);
        }
    }
    Some(out)
}

// ---------------- display width ----------------

pub fn char_width(c: char) -> usize {
    let cp = c as u32;
    if cp == 0 {
        return 0;
    }
    if cp < 0x20 || (0x7f..0xa0).contains(&cp) {
        return 0;
    }
    // combining marks
    if (0x0300..=0x036f).contains(&cp) || (0x200b..=0x200f).contains(&cp) || cp == 0xfe0f {
        return 0;
    }
    if is_wide(cp) {
        2
    } else {
        1
    }
}

fn is_wide(cp: u32) -> bool {
    (0x1100..=0x115f).contains(&cp)
        || (0x2e80..=0x303e).contains(&cp)
        || (0x3041..=0x33ff).contains(&cp)
        || (0x3400..=0x4dbf).contains(&cp)
        || (0x4e00..=0x9fff).contains(&cp)
        || (0xa000..=0xa4cf).contains(&cp)
        || (0xac00..=0xd7a3).contains(&cp)
        || (0xf900..=0xfaff).contains(&cp)
        || (0xfe30..=0xfe4f).contains(&cp)
        || (0xff00..=0xff60).contains(&cp)
        || (0xffe0..=0xffe6).contains(&cp)
        || (0x1f300..=0x1f64f).contains(&cp)
        || (0x1f900..=0x1f9ff).contains(&cp)
        || (0x20000..=0x3fffd).contains(&cp)
}

pub fn display_width(s: &str) -> usize {
    s.chars().map(char_width).sum()
}

// ---------------- line breaking (UAX #14 subset) ----------------

#[derive(Clone, Copy, PartialEq, Debug)]
enum Lb {
    AL,
    SP,
    EX,
    QU,
    PR,
    PO,
    OP,
    CP,
    CL,
    IS,
    HY,
    SY,
    NU,
    BA,
    ID,
    GL,
    CM,
}

fn lb_class(c: char) -> Lb {
    use Lb::*;
    match c {
        ' ' => SP,
        '\t' => BA,
        '!' | '?' => EX,
        '"' | '\'' => QU,
        '$' | '+' | '\\' => PR,
        '%' => PO,
        '(' | '[' | '{' => OP,
        ')' | ']' => CP,
        '}' => CL,
        ',' | '.' | ':' | ';' => IS,
        '-' => HY,
        '/' => SY,
        '0'..='9' => NU,
        '|' => BA,
        '\u{a0}' => GL,
        c if (c as u32) < 0x20 => CM,
        c if is_wide(c as u32) => ID,
        _ => AL,
    }
}

/// Returns byte indices of allowed break opportunities (break before index), excluding 0 and len.
fn line_break_opportunities(s: &str) -> Vec<usize> {
    use Lb::*;
    let chars: Vec<(usize, char)> = s.char_indices().collect();
    let mut result = vec![];
    if chars.is_empty() {
        return result;
    }
    let mut prev = lb_class(chars[0].1);
    if prev == CM {
        prev = AL;
    }
    // class of last non-space char before a run of spaces
    let mut before_sp = prev;
    for k in 1..chars.len() {
        let (idx, c) = chars[k];
        let mut cur = lb_class(c);
        // LB9: X CM* -> X
        if cur == CM {
            if prev != SP {
                continue;
            }
            cur = AL;
        }
        let brk = (|| {
            if cur == SP {
                return false; // LB7
            }
            if matches!(cur, CL | CP | EX | IS | SY) {
                return false; // LB13
            }
            // LB14: OP SP* ×
            if prev == OP || (prev == SP && before_sp == OP) {
                return false;
            }
            // LB15: QU SP* × OP
            if cur == OP && (prev == QU || (prev == SP && before_sp == QU)) {
                return false;
            }
            if prev == SP {
                return true; // LB18
            }
            if cur == QU || prev == QU {
                return false; // LB19
            }
            if cur == GL || prev == GL {
                return false;
            }
            if matches!(cur, BA | HY) {
                return false; // LB21
            }
            // LB23
