#[derive(Clone, Debug)]
struct Word<'a> {
    word: &'a str,
    whitespace: &'a str,
    penalty: &'a str,
    width: usize,
}

impl<'a> Word<'a> {
    fn from(s: &'a str) -> Word<'a> {
        let trimmed = s.trim_end_matches(' ');
        Word {
            word: trimmed,
            whitespace: &s[trimmed.len()..],
            penalty: "",
            width: display_width(trimmed),
        }
    }
}

fn find_words(line: &str) -> Vec<Word<'_>> {
    let opps: Vec<usize> = line_break_opportunities(line)
        .into_iter()
        .filter(|&idx| !line[..idx].ends_with('-') && !line[..idx].ends_with('\u{ad}'))
        .collect();
    let mut words = vec![];
    let mut start = 0;
    for idx in opps {
        words.push(Word::from(&line[start..idx]));
        start = idx;
    }
    if start < line.len() {
        words.push(Word::from(&line[start..]));
    }
    words
}

fn split_words<'a>(words: Vec<Word<'a>>) -> Vec<Word<'a>> {
    let mut out = vec![];
    for word in words {
        let w = word.word;
        let mut splits = vec![];
        for (idx, _) in w.match_indices('-') {
            let prev = w[..idx].chars().next_back();
            let next = w[idx + 1..].chars().next();
            if prev.map(|c| c.is_alphanumeric()).unwrap_or(false)
                && next.map(|c| c.is_alphanumeric()).unwrap_or(false)
            {
                splits.push(idx + 1);
            }
        }
        let mut prev = 0;
        for idx in splits {
            let need_hyphen = !w[..idx].ends_with('-');
            out.push(Word {
                word: &w[prev..idx],
                whitespace: "",
                penalty: if need_hyphen { "-" } else { "" },
                width: display_width(&w[prev..idx]),
            });
            prev = idx;
        }
        if prev < w.len() || prev == 0 {
            out.push(Word {
                word: &w[prev..],
                whitespace: word.whitespace,
                penalty: word.penalty,
                width: display_width(&w[prev..]),
            });
        }
    }
    out
}

fn break_words<'a>(words: Vec<Word<'a>>, line_width: usize) -> Vec<Word<'a>> {
    let mut out = vec![];
    for word in words {
        if word.width > line_width {
            let mut offset = 0;
            let mut width = 0;
            for (idx, ch) in word.word.char_indices() {
                let cw = char_width(ch);
                if width > 0 && width + cw > line_width {
                    out.push(Word {
                        word: &word.word[offset..idx],
                        whitespace: "",
                        penalty: "",
                        width,
                    });
                    offset = idx;
                    width = cw;
                    continue;
                }
                width += cw;
            }
            if offset < word.word.len() {
                out.push(Word {
                    word: &word.word[offset..],
                    whitespace: word.whitespace,
                    penalty: word.penalty,
                    width,
                });
            }
        } else {
            out.push(word);
        }
    }
    out
}

fn wrap_optimal_fit(fragments: &[Word], line_width: f64) -> Vec<(usize, usize)> {
    let n = fragments.len();
    let mut widths = Vec::with_capacity(n + 1);
    let mut w = 0.0f64;
    widths.push(w);
    for f in fragments {
        w += f.width as f64 + f.whitespace.len() as f64;
        widths.push(w);
    }
    let target = line_width.max(1.0);
    let cost_fn = |minima: &Vec<(usize, f64)>, i: usize, j: usize| -> f64 {
        let lw = widths[j] - widths[i] - fragments[j - 1].whitespace.len() as f64
            + fragments[j - 1].penalty.len() as f64;
        let mut cost = minima[i].1 + 1000.0;
        if lw > target {
            let overflow = lw - target;
            cost += overflow * 2500.0;
        } else if j < n {
            let gap = target - lw;
            cost += gap * gap;
        } else if i + 1 == j && lw < target / 4.0 {
            cost += 25.0;
        }
        if !fragments[j - 1].penalty.is_empty() {
            cost += 25.0;
        }
        cost
    };
    let minima = online_column_minima(n + 1, &cost_fn);
    let mut lines = vec![];
    let mut pos = n;
    loop {
        let prev = minima[pos].0;
        lines.push((prev, pos));
        pos = prev;
        if pos == 0 {
            break;
        }
    }
    lines.reverse();
    lines
}

fn smawk_inner<M: Fn(usize, usize) -> f64>(matrix: &M, rows: &[usize], cols: &[usize], minima: &mut [usize]) {
    if cols.is_empty() {
        return;
    }
    let mut stack: Vec<usize> = Vec::with_capacity(cols.len());
    for &r in rows {
        while !stack.is_empty()
            && matrix(stack[stack.len() - 1], cols[stack.len() - 1]) > matrix(r, cols[stack.len() - 1])
        {
            stack.pop();
        }
        if stack.len() != cols.len() {
            stack.push(r);
        }
    }
    let rows = &stack;
    let odd_cols: Vec<usize> = cols.iter().enumerate().filter(|(i, _)| i % 2 == 1).map(|(_, c)| *c).collect();
    smawk_inner(matrix, rows, &odd_cols, minima);
    let mut r = 0;
    let mut c = 0;
    while c < cols.len() {
        let col = cols[c];
        let mut row = rows[r];
        let last_row = if c == cols.len() - 1 { rows[rows.len() - 1] } else { minima[cols[c + 1]] };
        let mut pair = (matrix(row, col), row);
        while row != last_row {
            r += 1;
            row = rows[r];
            let v = matrix(row, col);
            if v < pair.0 || (v == pair.0 && row < pair.1) {
                pair = (v, row);
            }
        }
        minima[col] = pair.1;
        c += 2;
    }
}

fn online_column_minima<F: Fn(&Vec<(usize, f64)>, usize, usize) -> f64>(size: usize, matrix: &F) -> Vec<(usize, f64)> {
    let mut result: Vec<(usize, f64)> = vec![(0, 0.0)];
    if size <= 1 {
        return result;
    }
    let mut finished = 0usize;
    let mut base = 0usize;
    let mut tentative = 0usize;
    while finished < size - 1 {
        let i = finished + 1;
        if i > tentative {
            let rows: Vec<usize> = (base..finished + 1).collect();
            tentative = std::cmp::min(finished + rows.len(), size - 1);
            let cols: Vec<usize> = (finished + 1..tentative + 1).collect();
            let mut minima = vec![0usize; tentative + 1];
            {
                let res = &result;
                let m = |a: usize, b: usize| matrix(res, a, b);
                smawk_inner(&m, &rows, &cols, &mut minima);
            }
            for col in cols {
                let row = minima[col];
                let v = matrix(&result, row, col);
                if col >= result.len() {
                    result.push((row, v));
                } else if v < result[col].1 {
                    result[col] = (row, v);
                }
            }
            finished = i;
            continue;
        }
        let diag = matrix(&result, i - 1, i);
        if diag < result[i].1 {
            result[i] = (i - 1, diag);
            base = i - 1;
            tentative = i;
            finished = i;
            continue;
        }
        if matrix(&result, i - 1, tentative) >= result[tentative].1 {
            finished = i;
            continue;
        }
        base = i - 1;
        tentative = i;
        finished = i;
    }
    result
}

/// Wrap text like textwrap::wrap(text, width) (optimal fit, unicode breaks, hyphen splitting)
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = vec![];
    for line in text.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.len() < width {
            lines.push(line.trim_end_matches(' ').to_string());
            continue;
        }
        let words = find_words(line);
        let words = split_words(words);
        let words = break_words(words, width);
        if words.is_empty() {
            lines.push(String::new());
            continue;
        }
        let wrapped = wrap_optimal_fit(&words, width as f64);
        for (s, e) in wrapped {
            let frags = &words[s..e];
            let mut out = String::new();
            for (k, f) in frags.iter().enumerate() {
                out.push_str(f.word);
                if k + 1 < frags.len() {
                    out.push_str(f.whitespace);
                } else {
                    out.push_str(f.penalty);
                }
            }
            lines.push(out);
        }
    }
    lines
}
