    let mut tentative = 0usize;
    while finished < size - 1 {
        let i = finished + 1;
        if i > tentative {
            let rows: Vec<usize> = (base..finished + 1).collect();
            tentative = std::cmp::min(finished + rows.len(), size - 1);
            let cols: Vec<usize> = (finished + 1..tentative + 1).collect();
            let mut minima = vec![0usize; tentative + 1];
            {
                let res = &result;
                let m = |a: usize, b: usize| matrix(res, a, b);
                smawk_inner(&m, &rows, &cols, &mut minima);
            }
            for col in cols {
                let row = minima[col];
                let v = matrix(&result, row, col);
                if col >= result.len() {
                    result.push((row, v));
                } else if v < result[col].1 {
                    result[col] = (row, v);
                }
            }
            finished = i;
            continue;
        }
        let diag = matrix(&result, i - 1, i);
        if diag < result[i].1 {
            result[i] = (i - 1, diag);
            base = i - 1;
            tentative = i;
            finished = i;
            continue;
        }
        if matrix(&result, i - 1, tentative) >= result[tentative].1 {
            finished = i;
            continue;
        }
        base = i - 1;
        tentative = i;
        finished = i;
    }
    result
}

/// Wrap text like textwrap::wrap(text, width) (optimal fit, unicode breaks, hyphen splitting)
pub fn wrap(text: &str, width: usize) -> Vec<String> {
    let mut lines = vec![];
    for line in text.split('\n') {
        let line = line.strip_suffix('\r').unwrap_or(line);
        if line.len() < width {
            lines.push(line.trim_end_matches(' ').to_string());
            continue;
        }
        let words = find_words(line);
        let words = split_words(words);
        let words = break_words(words, width);
        if words.is_empty() {
            lines.push(String::new());
            continue;
        }
        let wrapped = wrap_optimal_fit(&words, width as f64);
        for (s, e) in wrapped {
            let frags = &words[s..e];
            let mut out = String::new();
            for (k, f) in frags.iter().enumerate() {
                out.push_str(f.word);
                if k + 1 < frags.len() {
                    out.push_str(f.whitespace);
                } else {
                    out.push_str(f.penalty);
                }
            }
            lines.push(out);
        }
    }
    lines
}
