use crate::command::Command;
use crate::param::*;
use crate::parser::{ChoiceValue, DefaultValue};
use std::collections::HashMap;

#[derive(Debug, Clone)]
pub struct FlagArg {
    pub key: String,
    pub values: Vec<String>,
    pub param: Option<usize>, // index into cmd.flag_options
    pub has_eq: bool,
    pub prefixed_key: Option<String>,
}

pub struct Matcher<'a> {
    pub root: &'a Command,
    pub args: Vec<String>,
    pub cmds: Vec<(&'a Command, usize)>,
    pub flag_args: Vec<Vec<FlagArg>>,
    pub positional_args: Vec<String>,
    pub dashes: Vec<usize>,
    pub level_has_args: Vec<bool>,
    pub choice_values: HashMap<String, Vec<String>>,
}

#[derive(Debug, Clone)]
pub enum ArgcValue {
    Single(String, String),
    SingleFn(String, String),
    Multiple(String, Vec<String>),
    Map(String, Vec<(String, String)>),
    Env(String, String),
    EnvFn(String, String),
}

pub enum MatchResult {
    Values(Vec<ArgcValue>),
    Help(String),
    Version(String),
    Error(String),
}

pub fn signs_of(cmd: &Command) -> (bool, bool) {
    let mut minus = false;
    let mut plus = false;
    for p in &cmd.flag_options {
        for n in p.list_names() {
            if n.starts_with('+') {
                plus = true;
            } else if n.starts_with('-') {
                minus = true;
            }
        }
    }
    (minus, plus)
}

pub fn maybe_flag(signs: (bool, bool), arg: &str) -> bool {
    let mut cond = false;
    if signs.1 && arg.starts_with('+') {
        let mut chars = arg.chars();
        chars.next();
        if let Some(c) = chars.next() {
            if c != '+' {
                cond = true;
            }
        }
    }
    if signs.0 && arg.starts_with('-') && (arg.len() < 3 || !arg.starts_with("---")) {
        cond = true;
    }
    if !cond {
        return false;
    }
    let value = match arg.split_once('=') {
        Some((k, _)) => k,
        None => arg,
    };
    if value.chars().any(|c| c.is_whitespace()) {
        return false;
    }
    true
}

pub fn is_help_name(arg: &str) -> bool {
    matches!(arg, "-h" | "-help" | "--help")
}

pub fn is_version_name(arg: &str) -> bool {
    matches!(arg, "-V" | "-version" | "--version")
}

fn terminated_mode(cmd: &Command, positional_args: &[String]) -> bool {
    if let Some(last) = cmd.positionals.last() {
        if last.terminated && !positional_args.is_empty() && positional_args.len() + 1 >= cmd.positionals.len() {
            return true;
        }
    }
    false
}

impl<'a> Matcher<'a> {
    pub fn new(root: &'a Command, args: &[String]) -> Self {
        let mut m = Matcher {
            root,
            args: args.to_vec(),
            cmds: vec![(root, 0)],
            flag_args: vec![vec![]],
            positional_args: vec![],
            dashes: vec![],
            level_has_args: vec![false],
            choice_values: HashMap::new(),
        };
        m.run();
        m
    }

    fn cur(&self) -> &'a Command {
        self.cmds.last().unwrap().0
    }

    fn level(&self) -> usize {
        self.cmds.len() - 1
    }

    fn push_flag(&mut self, fa: FlagArg) {
        let level = self.level();
        self.flag_args[level].push(fa);
    }

    fn switch_default(&mut self, arg_index: usize) -> bool {
        let cmd = self.cur();
        if !self.positional_args.is_empty() {
            return false;
        }
        if let Some(idx) = cmd.subcommands.iter().position(|c| c.default_subcommand) {
            let sub = &cmd.subcommands[idx];
            self.cmds.push((sub, arg_index));
            self.flag_args.push(vec![]);
            self.level_has_args.push(false);
            return true;
        }
        false
    }

    fn run(&mut self) {
        let args = self.args.clone();
        let len = args.len();
        let mut i = 1;
        while i < len {
            let arg = args[i].as_str();
            let cmd = self.cur();
            let level = self.level();
            self.level_has_args[level] = true;
            if cmd.delegated() || terminated_mode(cmd, &self.positional_args) {
                self.positional_args.push(arg.to_string());
                i += 1;
                continue;
            }
            if arg == "--" {
                if self.dashes.is_empty() {
                    self.dashes.push(self.positional_args.len());
                } else {
                    self.positional_args.push(arg.to_string());
                }
                i += 1;
                continue;
            }
            if !self.dashes.is_empty() {
                self.positional_args.push(arg.to_string());
                i += 1;
                continue;
            }
            if cmd.no_flags_options_subcommands()
                && !(is_help_name(arg) || (is_version_name(arg) && cmd.flag_options.iter().any(|p| p.is_version)))
            {
                self.positional_args.push(arg.to_string());
                i += 1;
                continue;
            }
            let signs = signs_of(cmd);
            if arg.len() > 1 && maybe_flag(signs, arg) {
                i = self.handle_flag(i, signs);
                continue;
            }
            if self.positional_args.is_empty() {
                if let Some(sub) = cmd.find_subcommand(arg) {
                    self.cmds.push((sub, i));
                    self.flag_args.push(vec![]);
                    self.level_has_args.push(false);
                    i += 1;
                    continue;
                }
                if self.switch_default(i) {
                    continue;
                }
            }
            self.positional_args.push(arg.to_string());
            i += 1;
        }
        // no args at all at this level: switch default subcommand
        let level = self.level();
        if !self.level_has_args[level] {
            let cmd = self.cur();
            if cmd.subcommands.iter().any(|c| c.default_subcommand) && cmd.command_fn.is_none() {
                self.switch_default(len);
            }
        }
    }

    fn take_values(&self, start: usize, max: usize, signs: (bool, bool)) -> Vec<String> {
        let mut values = vec![];
        let mut j = start;
        while j < self.args.len() && values.len() < max {
            let a = self.args[j].as_str();
            if a.len() > 1 && maybe_flag(signs, a) {
                break;
            }
            values.push(a.to_string());
            j += 1;
        }
        values
    }

    // returns next index
    fn handle_flag(&mut self, i: usize, signs: (bool, bool)) -> usize {
        let cmd = self.cur();
        let arg = self.args[i].clone();
        if let Some((k, v)) = arg.split_once('=') {
            if let Some(idx) = cmd.flag_options.iter().position(|p| p.long_name() == k || p.short.as_deref() == Some(k)) {
                let p = &cmd.flag_options[idx];
                if p.prefixed && p.long_name() != k {
                    // unreachable
                }
                self.push_flag(FlagArg {
                    key: k.to_string(),
                    values: vec![v.to_string()],
                    param: Some(idx),
                    has_eq: true,
                    prefixed_key: if p.prefixed { Some(String::new()) } else { None },
                });
                return i + 1;
            }
            if let Some(fa) = self.find_prefixed(cmd, &arg) {
                self.push_flag(fa);
                return i + 1;
            }
            if self.switch_default(i) {
                return i;
            }
            self.push_flag(FlagArg { key: k.to_string(), values: vec![], param: None, has_eq: true, prefixed_key: None });
            return i + 1;
        }
        if let Some(idx) = cmd.flag_options.iter().position(|p| p.long_name() == arg || p.short.as_deref() == Some(arg.as_str())) {
            return self.match_param(i, idx, signs);
        }
        if let Some(fa) = self.find_prefixed(cmd, &arg) {
            self.push_flag(fa);
            return i + 1;
        }
        if self.root.combine_shorts {
            if let Some(next) = self.try_combine_shorts(i, signs) {
                return next;
            }
        }
        if self.switch_default(i) {
            return i;
        }
        self.push_flag(FlagArg { key: arg.clone(), values: vec![], param: None, has_eq: false, prefixed_key: None });
        i + 1
    }

    fn match_param(&mut self, i: usize, idx: usize, signs: (bool, bool)) -> usize {
        let cmd = self.cur();
        let p = &cmd.flag_options[idx];
        let arg = self.args[i].clone();
        if p.flag {
            self.push_flag(FlagArg { key: arg, values: vec![], param: Some(idx), has_eq: false, prefixed_key: if p.prefixed { Some(String::new()) } else { None } });
            return i + 1;
        }
        if p.terminated {
            let values: Vec<String> = self.args[i + 1..].to_vec();
            let n = values.len();
            self.push_flag(FlagArg { key: arg, values, param: Some(idx), has_eq: false, prefixed_key: None });
            return i + 1 + n;
        }
        if p.assigned {
            self.push_flag(FlagArg { key: arg, values: vec![], param: Some(idx), has_eq: false, prefixed_key: None });
            return i + 1;
        }
        let values = self.take_values(i + 1, p.num_args.1, signs);
        let n = values.len();
        self.push_flag(FlagArg { key: arg, values, param: Some(idx), has_eq: false, prefixed_key: if p.prefixed { Some(String::new()) } else { None } });
        i + 1 + n
    }

    fn find_prefixed(&self, cmd: &Command, arg: &str) -> Option<FlagArg> {
        for (idx, p) in cmd.flag_options.iter().enumerate() {
            if !p.prefixed {
                continue;
            }
            let ln = p.long_name();
            if arg.len() > ln.len() && arg.starts_with(&ln) {
                let rest = &arg[ln.len()..];
                let (k, v, eq) = match rest.split_once('=') {
                    Some((k, v)) => (k.to_string(), v.to_string(), true),
                    None => (rest.to_string(), "1".to_string(), false),
                };
                if p.flag {
                    return Some(FlagArg { key: ln.clone(), values: vec![v], param: Some(idx), has_eq: true, prefixed_key: Some(k) });
                }
                let _ = eq;
                return Some(FlagArg { key: ln.clone(), values: vec![v], param: Some(idx), has_eq: false, prefixed_key: Some(k) });
            }
        }
        None
    }

    fn try_combine_shorts(&mut self, i: usize, signs: (bool, bool)) -> Option<usize> {
        let cmd = self.cur();
        let arg = self.args[i].clone();
        let mut chars = arg.chars();
        let sign = chars.next()?;
        if sign != '-' && sign != '+' {
            return None;
        }
        let rest: Vec<char> = chars.collect();
        if rest.len() < 2 {
            return None;
        }
        if rest.contains(&'-') {
            return None;
        }
        let mut idxs = vec![];
        for c in &rest {
            let name = format!("{}{}", sign, c);
            let idx = cmd.flag_options.iter().position(|p| p.long_name() == name || p.short.as_deref() == Some(name.as_str()))?;
            idxs.push((name, idx));
        }
        let n = idxs.len();
        let mut next = i + 1;
        for (k, (name, idx)) in idxs.into_iter().enumerate() {
            let p = &cmd.flag_options[idx];
            if p.flag {
                self.push_flag(FlagArg { key: name, values: vec![], param: Some(idx), has_eq: false, prefixed_key: None });
            } else if k + 1 == n {
                if p.terminated {
                    let values: Vec<String> = self.args[i + 1..].to_vec();
                    next = i + 1 + values.len();
                    self.push_flag(FlagArg { key: name, values, param: Some(idx), has_eq: false, prefixed_key: None });
                } else {
                    let values = self.take_values(i + 1, p.num_args.1, signs);
                    next = i + 1 + values.len();
                    self.push_flag(FlagArg { key: name, values, param: Some(idx), has_eq: false, prefixed_key: None });
                }
            } else {
                self.push_flag(FlagArg { key: name, values: vec![], param: Some(idx), has_eq: false, prefixed_key: None });
            }
        }
        Some(next)
    }

    // ---------------- positional matching ----------------

    pub fn match_positionals(&self) -> Vec<Vec<String>> {
        let cmd = self.cur();
        let params: Vec<bool> = cmd.positionals.iter().map(|p| p.multiple).collect();
        let args = &self.positional_args;
        let mut out: Vec<Vec<String>> = vec![];
        let args_len = args.len();
        if args_len == 0 {
            return out;
        }
        let params_len = params.len();
        let dash = self.dashes.first().copied().unwrap_or(0);
        let mut arg_index = 0;
        let mut param_index = 0;
        while param_index < params_len && arg_index < args_len {
            let takes = if params[param_index] {
                if param_index == 0 && dash > 0 && params_len == 2 && params[1] {
                    dash
                } else {
                    let arg_diff = args_len - arg_index;
                    let param_diff = params_len - param_index;
                    if arg_diff > param_diff {
                        arg_diff - param_diff + 1
                    } else {
                        1
                    }
                }
            } else {
                1
            };
            let end = (arg_index + takes).min(args_len);
            out.push(args[arg_index..end].to_vec());
            arg_index += takes;
            param_index += 1;
        }
        if arg_index < args_len {
            out.push(args[arg_index..].to_vec());
        }
        out
    }

    pub fn get_env(&self, name: &str) -> Option<String> {
        std::env::var(name).ok()
    }
}

pub fn choice_values_static(choice: &Option<ChoiceValue>) -> Option<Vec<String>> {
    match choice {
        Some(ChoiceValue::Values(v)) => Some(v.clone()),
        _ => None,
    }
}

pub fn default_to_value(var: &str, default: &Option<DefaultValue>, multiple: bool) -> Option<ArgcValue> {
    match default {
        Some(DefaultValue::Value(v)) => {
            if multiple {
                Some(ArgcValue::Multiple(var.to_string(), vec![v.clone()]))
            } else {
                Some(ArgcValue::Single(var.to_string(), v.clone()))
            }
        }
        Some(DefaultValue::Fn(f)) => Some(ArgcValue::SingleFn(var.to_string(), f.clone())),
        None => None,
    }
}

#[allow(dead_code)]
pub fn param_render(p: &FlagOptionParam) -> String {
    p.render_long_name_notations()
}
