pub fn run_choice_fns(script_path: &str, args: &[String], fns: &[String], vars_b64: &str) -> HashMap<String, Vec<String>> {
    let mut map = HashMap::new();
    if fns.is_empty() {
        return map;
    }
    let shell = match crate::runner::get_shell_path() {
        Ok(s) => s,
        Err(_) => return map,
    };
    let handles: Vec<_> = fns
        .iter()
        .map(|f| {
            let f = f.clone();
            let shell = shell.clone();
            let script = script_path.to_string();
            let args = args.to_vec();
            let vars = vars_b64.to_string();
            std::thread::spawn(move || {
                let mut cmd = std::process::Command::new(&shell);
                cmd.arg("--noprofile").arg("--norc").arg(&script).arg("___internal___").arg(&f);
                cmd.args(&args);
                cmd.env("ARGC_VARS", vars);
                cmd.env("ARGC_OS", crate::runner::os_name());
                cmd.stdin(std::process::Stdio::null());
                cmd.stderr(std::process::Stdio::null());
                let out = cmd.output();
                let lines: Vec<String> = match out {
                    Ok(o) if o.status.success() => String::from_utf8_lossy(&o.stdout)
                        .lines()
                        .map(|l| l.trim().to_string())
                        .filter(|l| !l.is_empty())
                        .collect(),
                    _ => vec![],
                };
                (f, lines)
            })
        })
        .collect();
    for h in handles {
        if let Ok((f, lines)) = h.join() {
            map.insert(f, lines);
        }
    }
    map
}

fn collect_choice_fns(m: &Matcher) -> Vec<String> {
    let mut fns: Vec<String> = vec![];
    let mut add = |c: &Option<ChoiceValue>| {
        if let Some(ChoiceValue::Fn(f, true)) = c {
            if !fns.contains(f) {
                fns.push(f.clone());
            }
        }
    };
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        for fa in list {
            if let Some(idx) = fa.param {
                add(&cmd.flag_options[idx].choice);
            }
        }
        for p in &cmd.flag_options {
            if let Some(e) = &p.env {
                if std::env::var(e).is_ok() {
                    add(&p.choice);
                }
            }
        }
    }
    let cmd = m.cmds.last().unwrap().0;
    for p in &cmd.positionals {
        add(&p.choice);
    }
    for e in &cmd.envs {
        add(&e.choice);
    }
    fns
}

fn check_choice(
    value: &str,
    choice: &Option<ChoiceValue>,
    cache: &HashMap<String, Vec<String>>,
) -> Result<(), Vec<String>> {
    match choice {
        Some(ChoiceValue::Values(vs)) => {
            if vs.iter().any(|v| v == value) {
                Ok(())
            } else {
                Err(vs.clone())
            }
        }
        Some(ChoiceValue::Fn(f, true)) => {
            let empty = vec![];
            let vs = cache.get(f).unwrap_or(&empty);
            if vs.iter().any(|v| v == value) {
                Ok(())
            } else {
                Err(vs.clone())
            }
        }
        _ => Ok(()),
    }
}

fn invalid_value_msg(value: &str, target: &str, list: &[String]) -> String {
    format!("error: invalid value `{}` for `{}`\n  [possible values: {}]", value, target, list.join(", "))
}

fn parse_env_flag(value: &str) -> Option<bool> {
    match value {
        "true" | "1" => Some(true),
        "false" | "0" => Some(false),
        _ => None,
    }
}

pub fn evaluate(m: &Matcher, cache: &HashMap<String, Vec<String>>) -> Outcome {
    let last = m.cmds.last().unwrap().0;
    // 1. scan
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        for fa in list {
            match fa.param {
                None => {
                    if is_help_name(&fa.key) {
                        return Outcome::Help(render_help(last));
                    }
                    if is_version_name(&fa.key) && cmd.flag_options.iter().any(|p| p.is_version) {
                        return Outcome::Version(render_version(last));
                    }
                    return Outcome::Error(format!("error: unexpected argument `{}` found", fa.key));
                }
                Some(idx) => {
                    let p = &cmd.flag_options[idx];
                    if p.is_help {
                        return Outcome::Help(render_help(last));
                    }
                    if p.is_version {
                        return Outcome::Version(render_version(last));
                    }
                    if p.id == "help" {
                        return Outcome::Help(render_help(last));
                    }
                }
            }
        }
    }
    // 2. per arg checks
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        let mut seen: Vec<usize> = vec![];
        for fa in list {
            let idx = fa.param.unwrap();
            let p = &cmd.flag_options[idx];
            if p.flag {
                if fa.has_eq && !p.prefixed {
                    return Outcome::Error(format!("error: flag `{}` don't accept any value", p.long_name()));
                }
                if p.prefixed && fa.prefixed_key.as_deref().map(|k| !k.is_empty()).unwrap_or(false) {
                    return Outcome::Error(format!("error: flag `{}` don't accept any value", p.long_name()));
                }
            } else {
                let n = fa.values.len();
                if n < p.num_args.0 || n > p.num_args.1 {
                    return Outcome::Error(format!(
                        "error: incorrect number of values for `{}`",
                        p.render_long_name_notations()
                    ));
                }
                let values = split_delim(&fa.values, p.delimiter);
                for v in &values {
                    if let Err(list) = check_choice(v, &p.choice, cache) {
                        return Outcome::Error(invalid_value_msg(v, &p.render_first_notation(), &list));
                    }
                }
            }
            if seen.contains(&idx) && !p.multiple_occurs && !p.prefixed {
                return Outcome::Error(format!(
                    "error: the argument `{}` cannot be used multiple times",
                    p.long_name()
                ));
            }
            seen.push(idx);
        }
    }
    // 3. env bound params (flags/options)
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        for (idx, p) in cmd.flag_options.iter().enumerate() {
            if p.is_help || p.is_version {
                continue;
            }
            if list.iter().any(|fa| fa.param == Some(idx)) {
                continue;
            }
            let Some(env) = &p.env else { continue };
            let Ok(value) = std::env::var(env) else { continue };
            if p.flag {
                if parse_env_flag(&value).is_none() {
                    return Outcome::Error(format!(
                        "error: environment variable `{}` has invalid value for param '{}'",
                        env,
                        p.long_name()
                    ));
                }
            } else {
                let values = split_delim(&[value.clone()], p.delimiter);
                for v in &values {
                    if let Err(list) = check_choice(v, &p.choice, cache) {
                        return Outcome::Error(format!(
                            "error: invalid value `{}` for environment variable `{}` that bound to `{}`\n  [possible values: {}]",
                            v,
                            env,
                            p.long_name(),
                            list.join(", ")
                        ));
                    }
                }
            }
        }
    }
    // 4. missing required options
    let mut missing: Vec<String> = vec![];
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        for (idx, p) in cmd.flag_options.iter().enumerate() {
            if !p.required {
                continue;
            }
            if list.iter().any(|fa| fa.param == Some(idx)) {
                continue;
            }
            if let Some(env) = &p.env {
                if std::env::var(env).is_ok() {
                    continue;
                }
            }
            missing.push(p.render_usage());
        }
    }
    if !missing.is_empty() {
        return Outcome::Error(format!(
            "error: the following required arguments were not provided:\n  {}",
            missing.join("\n  ")
        ));
    }
    // 5. help positional
    if m.positional_args.first().map(|v| v == "help").unwrap_or(false) {
        if m.positional_args.len() == 1 {
            return Outcome::Help(render_help(last));
        }
        let name = &m.positional_args[1];
        match last.find_subcommand(name) {
            Some(sub) => return Outcome::Help(render_help(sub)),
            None => {
                return Outcome::Error(format!(
                    "error: invalid value `{}` for `<command>`\n  [possible values: {}]",
                    name,
                    last.list_subcommand_names().join(", ")
                ))
            }
        }
    }
    // 6. subcommands
    if !last.subcommands.is_empty() {
        if m.positional_args.is_empty() {
            if last.command_fn.is_none() {
                let level = m.cmds.len() - 1;
                if !m.level_has_args[level] {
                    return Outcome::Help(render_help(last));
                }
                return Outcome::Error(format!(
                    "error: `{}` requires a subcommand but one was not provided\n  [subcommands: {}]",
                    last.full_name(),
                    last.list_subcommand_names().join(", ")
                ));
            }
        } else if last.positionals.is_empty() || last.command_fn.is_none() {
            return Outcome::Error(format!(
                "error: `{}` requires a subcommand but '{}' is not one of them\n  [subcommands: {}]",
                last.full_name(),
                m.positional_args[0],
                last.list_subcommand_names().join(", ")
            ));
        }
    }
    // 7. positionals
    let matched = m.match_positionals();
    let params_len = last.positionals.len();
    if params_len > 0 && matched.len() > params_len {
        return Outcome::Error(format!(
            "error: unexpected argument `{}` found",
            matched[params_len][0]
        ));
    }
    let mut pos_values: Vec<Option<ArgcValue>> = vec![];
    let mut pos_rendered: Vec<String> = vec![];
    let mut missing: Vec<String> = vec![];
    for (i, p) in last.positionals.iter().enumerate() {
        let var = p.var_name();
        if i < matched.len() {
            let values = split_delim(&matched[i], p.delimiter);
            for v in &values {
                if let Err(list) = check_choice(v, &p.choice, cache) {
                    return Outcome::Error(invalid_value_msg(v, &p.render_notation(), &list));
                }
            }
            for v in &values {
                pos_rendered.push(escape_shell_words(v));
            }
            if p.multiple {
                pos_values.push(Some(ArgcValue::Multiple(var, values)));
            } else {
                pos_values.push(Some(ArgcValue::Single(var, values.into_iter().next().unwrap_or_default())));
            }
            continue;
        }
        if let Some(env) = &p.env {
            if let Ok(value) = std::env::var(env) {
                let values = split_delim(&[value.clone()], p.delimiter);
                for v in &values {
                    if let Err(list) = check_choice(v, &p.choice, cache) {
                        return Outcome::Error(format!(
                            "error: invalid value `{}` for environment variable `{}` that bound to `{}`\n  [possible values: {}]",
                            v,
                            env,
                            p.render_notation(),
                            list.join(", ")
                        ));
                    }
                }
                for v in &values {
                    pos_rendered.push(escape_shell_words(v));
                }
                if p.multiple {
                    pos_values.push(Some(ArgcValue::Multiple(var, values)));
                } else {
                    pos_values.push(Some(ArgcValue::Single(var, value)));
                }
                continue;
            }
        }
        match &p.default {
            Some(DefaultValue::Value(v)) => {
                pos_rendered.push(escape_shell_words(v));
                pos_values.push(Some(ArgcValue::Single(var, v.clone())));
                continue;
            }
            Some(DefaultValue::Fn(f)) => {
                pos_rendered.push(format!("`{}`", f));
                pos_values.push(Some(ArgcValue::SingleFn(var, f.clone())));
                continue;
            }
            None => {}
        }
        if p.required {
            missing.push(p.render_notation());
        }
        pos_values.push(None);
    }
    if !missing.is_empty() {
        return Outcome::Error(format!(
            "error: the following required arguments were not provided:\n  {}",
            missing.join("\n  ")
        ));
    }
    if params_len == 0 {
        for v in &m.positional_args {
            pos_rendered.push(escape_shell_words(v));
        }
    } else if matched.len() > params_len {
        // unreachable (error above)
    }
    // 8. envs
    let mut missing: Vec<String> = vec![];
    for e in &last.envs {
        if e.required && std::env::var(&e.id).is_err() {
            missing.push(e.id.clone());
        }
    }
    if !missing.is_empty() {
        return Outcome::Error(format!(
            "error: the following required environments were not provided:\n  {}",
            missing.join("\n  ")
        ));
    }
    for e in &last.envs {
        if let Ok(value) = std::env::var(&e.id) {
            if let Err(list) = check_choice(&value, &e.choice, cache) {
                return Outcome::Error(format!(
                    "error: invalid value `{}` for environment variable `{}`\n  [possible values: {}]",
                    value,
                    e.id,
                    list.join(", ")
                ));
            }
        }
    }

    // build values
    let mut values: Vec<ArgcValue> = vec![];
    for e in &last.envs {
        if std::env::var(&e.id).is_ok() {
            continue;
        }
        match &e.default {
            Some(DefaultValue::Value(v)) => values.push(ArgcValue::Env(e.id.clone(), v.clone())),
            Some(DefaultValue::Fn(f)) => values.push(ArgcValue::EnvFn(e.id.clone(), f.clone())),
            None => {}
        }
    }
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        for (idx, p) in cmd.flag_options.iter().enumerate() {
            if p.is_help || p.is_version {
                continue;
            }
            if let Some(v) = flag_option_value(p, idx, list) {
                values.push(v);
            }
        }
    }
    for v in pos_values.into_iter().flatten() {
        values.push(v);
    }
    let mut tools: Vec<String> = vec![];
    for (c, _) in &m.cmds {
        for t in &c.require_tools {
            tools.push(t.clone());
        }
    }
    Outcome::Values(values, pos_rendered, last.command_fn.clone(), tools)
}

pub fn flag_option_value(p: &FlagOptionParam, idx: usize, list: &[FlagArg]) -> Option<ArgcValue> {
    let var = p.var_name();
    let given: Vec<&FlagArg> = list.iter().filter(|fa| fa.param == Some(idx)).collect();
    if !given.is_empty() {
        if p.prefixed {
            let mut kvs = vec![];
            for fa in &given {
                let key = fa.prefixed_key.clone().unwrap_or_default();
                let value = if p.flag { "1".to_string() } else { fa.values.first().cloned().unwrap_or_default() };
                kvs.push((key, value));
            }
            return Some(ArgcValue::Map(var, kvs));
        }
        if p.flag {
            if p.multiple_occurs {
                return Some(ArgcValue::Single(var, given.len().to_string()));
            }
            return Some(ArgcValue::Single(var, "1".to_string()));
        }
        let mut values = vec![];
        for fa in &given {
            values.extend(split_delim(&fa.values, p.delimiter));
        }
        if p.multiple_values {
            return Some(ArgcValue::Multiple(var, values));
        }
        return Some(ArgcValue::Single(var, values.into_iter().next().unwrap_or_default()));
    }
    if let Some(env) = &p.env {
        if let Ok(value) = std::env::var(env) {
            if p.flag {
                if parse_env_flag(&value) == Some(true) {
                    return Some(ArgcValue::Single(var, "1".to_string()));
                }
                return None;
            }
            let values = split_delim(&[value.clone()], p.delimiter);
            if p.multiple_values {
                return Some(ArgcValue::Multiple(var, values));
            }
            return Some(ArgcValue::Single(var, value));
        }
    }
    match &p.default {
        Some(DefaultValue::Value(v)) => Some(ArgcValue::Single(var, v.clone())),
        Some(DefaultValue::Fn(f)) => Some(ArgcValue::SingleFn(var, f.clone())),
        None => None,
    }
}

pub fn value_lines(v: &ArgcValue) -> Vec<String> {
    match v {
        ArgcValue::Single(name, value) => vec![format!("{}={}", name, escape_shell_words(value))],
        ArgcValue::SingleFn(name, f) => vec![format!("{}=`{}`", name, f)],
        ArgcValue::Multiple(name, values) => {
            let list: Vec<String> = values.iter().map(|v| escape_shell_words(v)).collect();
            vec![format!("{}=( {} )", name, list.join(" "))]
        }
        ArgcValue::Map(name, kvs) => {
            let mut out = vec![format!("declare -A {}", name)];
            for (k, v) in kvs {
                out.push(format!("{}[\"{}\"]={}", name, k, escape_shell_words(v)));
            }
            out
        }
        ArgcValue::Env(_, _) | ArgcValue::EnvFn(_, _) => vec![],
    }
}

const DOTENV_FN: &str = r#"_argc_load_dotenv() {
    local env_file="$1" env_vars=""
    if [[ -f "$env_file" ]]; then
        while IFS='=' read -r key value; do
            if [[ "$key" == $'#'* ]] || [[ -z "$key" ]]; then
                continue
            fi
            if [[ -z "${!key+x}" ]]; then
                env_vars="$env_vars $key=$value"
            fi
        done < <(cat "$env_file"; echo "")
        if [[ -n "$env_vars" ]]; then
            eval "export $env_vars"
        fi
    fi
}"#;

const REQUIRE_TOOLS_FN: &str = r#"_argc_require_tools() {
    local tool missing_tools=()
    for tool in "$@"; do
        if ! command -v "$tool" >/dev/null 2>&1; then
            missing_tools+=("$tool")
        fi
    done
    if [[ "${#missing_tools[@]}" -gt 0 ]]; then
        echo "error: missing tools: ${missing_tools[*]}" >&2
        exit 1
    fi
}"#;

pub fn to_bash(root: &Command, m: &Matcher, outcome: Outcome) -> String {
    match outcome {
        Outcome::Help(text) => format!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 0\n", text),
        Outcome::Version(text) => format!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 0\n", text),
        Outcome::Error(text) => format!("command cat >&2 <<-'EOF' \n{}\nEOF\nexit 1\n", text),
        Outcome::Values(values, positionals, fn_name, tools) => {
            let mut vars: Vec<String> = vec![];
            let mut exports: Vec<String> = vec![];
            for v in &values {
                match v {
                    ArgcValue::Env(name, value) => exports.push(format!("export {}={}", name, escape_shell_words(value))),
                    ArgcValue::EnvFn(name, f) => exports.push(format!("export {}=`{}`", name, f)),
                    _ => vars.extend(value_lines(v)),
                }
            }
            let args: Vec<String> = m.args.iter().map(|a| escape_shell_words(a)).collect();
            vars.push(format!("argc__args=( {} )", args.join(" ")));
            if let Some(f) = &fn_name {
                vars.push(format!("argc__fn={}", f));
            }
            vars.push(format!("argc__positionals=( {} )", positionals.join(" ")));
            let mut hooks_vars = vars.clone();
            if let Some(h) = &root.before_hook {
                hooks_vars.push(h.clone());
            }
            if let Some(h) = &root.after_hook {
                hooks_vars.push(h.clone());
            }
            let mut b64_src = hooks_vars.join(";");
            b64_src.push(';');
            let mut out: Vec<String> = vec![];
            out.push(format!("export ARGC_VARS={}", base64_encode(b64_src.as_bytes())));
            if let Some(dotenv) = &root.dotenv {
                out.push(DOTENV_FN.to_string());
                out.push(format!("_argc_load_dotenv {}", escape_shell_words(dotenv)));
            }
            out.extend(exports);
            out.extend(vars);
            if !tools.is_empty() {
                out.push(format!("\n{}\n_argc_require_tools {}\n", REQUIRE_TOOLS_FN, tools.join(" ")));
            }
            if let Some(h) = &root.before_hook {
                out.push(h.clone());
            }
            if let Some(f) = &fn_name {
                if positionals.is_empty() {
                    out.push(f.clone());
                } else {
                    out.push(format!("{} {}", f, positionals.join(" ")));
                }
            }
            if let Some(h) = &root.after_hook {
                out.push(h.clone());
            }
            let mut s = out.join("\n");
            s.push('\n');
            s
        }
    }
}

pub fn load_dotenv(root: &Command) {
    if let Some(path) = &root.dotenv {
        if let Ok(content) = std::fs::read_to_string(path) {
            for line in content.lines() {
                let line = line.trim();
                if line.is_empty() || line.starts_with('#') {
                    continue;
                }
                if let Some((k, v)) = line.split_once('=') {
                    let k = k.trim();
                    if std::env::var(k).is_err() {
                        std::env::set_var(k, v.trim());
                    }
                }
            }
        }
    }
}

/// Internal mode: lenient variables + call fn.
pub fn internal_output(root: &Command, fn_name: &str, args: &[String]) -> String {
    let args: Vec<String> = if args.is_empty() { vec!["prog".to_string()] } else { args.to_vec() };
    let m = Matcher::new(root, &args);
    let vars = lenient_vars(&m);
    let mut b64_src = vars.join(";");
    b64_src.push(';');
    let mut out = vec![format!("export ARGC_VARS={}", base64_encode(b64_src.as_bytes()))];
    out.extend(vars);
    let positionals = lenient_positionals(&m);
    if positionals.is_empty() {
        out.push(fn_name.to_string());
    } else {
        out.push(format!("{} {}", fn_name, positionals.join(" ")));
    }
    out.push("exit".to_string());
    let mut s = out.join("\n");
    s.push('\n');
    s
}

pub fn lenient_positionals(m: &Matcher) -> Vec<String> {
    let last = m.cmds.last().unwrap().0;
    let matched = m.match_positionals();
    let mut out = vec![];
    for (i, p) in last.positionals.iter().enumerate() {
        if i < matched.len() {
            for v in split_delim(&matched[i], p.delimiter) {
                out.push(escape_shell_words(&v));
            }
        } else {
            match &p.default {
                Some(DefaultValue::Value(v)) => out.push(escape_shell_words(v)),
                Some(DefaultValue::Fn(f)) => out.push(format!("`{}`", f)),
                None => {}
            }
        }
    }
    out
}

pub fn lenient_vars(m: &Matcher) -> Vec<String> {
    let mut vars = vec![];
    for (level, list) in m.flag_args.iter().enumerate() {
        let cmd = m.cmds[level].0;
        for (idx, p) in cmd.flag_options.iter().enumerate() {
            if p.is_help || p.is_version {
                continue;
            }
            if let Some(v) = flag_option_value(p, idx, list) {
                vars.extend(value_lines(&v));
            }
        }
    }
    let last = m.cmds.last().unwrap().0;
    let matched = m.match_positionals();
    for (i, p) in last.positionals.iter().enumerate() {
        let var = p.var_name();
        if i < matched.len() {
            let values = split_delim(&matched[i], p.delimiter);
            let v = if p.multiple {
                ArgcValue::Multiple(var, values)
            } else {
                ArgcValue::Single(var, values.into_iter().next().unwrap_or_default())
            };
            vars.extend(value_lines(&v));
        } else {
            match &p.default {
                Some(DefaultValue::Value(v)) => vars.extend(value_lines(&ArgcValue::Single(var, v.clone()))),
                Some(DefaultValue::Fn(f)) => vars.extend(value_lines(&ArgcValue::SingleFn(var, f.clone()))),
                None => {}
            }
        }
    }
    let args: Vec<String> = m.args.iter().map(|a| escape_shell_words(a)).collect();
    vars.push(format!("argc__args=( {} )", args.join(" ")));
    let (cmd_idx_level, _) = (m.cmds.len() - 1, 0);
    vars.push(format!("argc__cmd_arg_index={}", m.cmds[cmd_idx_level].1));
    if m.cmds.len() > 1 {
        if let Some(f) = &last.command_fn {
            vars.push(format!("argc__cmd_fn={}", f));
        }
    }
    // pending option
    if let Some(list) = m.flag_args.last() {
        if let Some(fa) = list.last() {
            if let Some(idx) = fa.param {
                let p = &last.flag_options[idx];
                if !p.flag && fa.values.is_empty() && m.args.last() == Some(&fa.key) {
                    vars.push(format!("argc__option={}", p.var_name()));
                }
            }
        }
    }
    vars.push(format!("argc__positionals=( {} )", lenient_positionals(m).join(" ")));
    vars
}

pub fn eval_main(root: &Command, script_path: &str, args: &[String]) -> String {
    load_dotenv(root);
    let m = Matcher::new(root, args);
    // pre-run choice fns
    let fns = collect_choice_fns(&m);
    let cache = if fns.is_empty() {
        HashMap::new()
    } else {
        let vars = lenient_vars(&m);
        let mut b64_src = vars.join(";");
        b64_src.push(';');
        run_choice_fns(script_path, args, &fns, &base64_encode(b64_src.as_bytes()))
    };
    let outcome = evaluate(&m, &cache);
    to_bash(root, &m, outcome)
}
