{"command":"cat > /workspace/src/compgen.rs <<'EOF'
use crate::command::Command;
use crate::eval::lenient_vars;
use crate::matcher::*;
use crate::param::*;
use crate::parser::ChoiceValue;
use crate::utils::base64_encode;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Color {
    Command,
    Flag,
    Option,
    Value,
    Dir,
    Exe,
    Symlink,
}

impl Color {
    fn generic(&self) -> &'static str {
        match self {
            Color::Command => "magenta",
            Color::Flag => "cyan",
            Color::Option => "cyan,bold",
            Color::Value => "default",
            Color::Dir => "blue,bold",
            Color::Exe => "green,bold",
            Color::Symlink => "cyan,bold",
        }
    }
    fn ansi(&self) -> &'static str {
        match self {
            Color::Command => "35",
            Color::Flag => "36",
            Color::Option => "1;36",
            Color::Value => "39",
            Color::Dir => "1;34",
            Color::Exe => "1;32",
            Color::Symlink => "1;36",
        }
    }
    fn elvish(&self) -> &'static str {
        match self {
            Color::Command => "magenta",
            Color::Flag => "cyan",
            Color::Option => "cyan bold",
            Color::Value => "default",
            Color::Dir => "blue bold",
            Color::Exe => "green bold",
            Color::Symlink => "cyan bold",
        }
    }
}

#[derive(Clone, Debug)]
pub struct CompItem {
    pub value: String,
    pub display: Option<String>,
    pub desc: String,
    pub nospace: bool,
    pub color: Color,
}

impl CompItem {
    fn new(value: &str, desc: &str, nospace: bool, color: Color) -> Self {
        CompItem { value: value.to_string(), display: None, desc: desc.to_string(), nospace, color }
    }
    fn display(&self) -> &str {
        self.display.as_deref().unwrap_or(&self.value)
    }
}

pub fn truncate_desc(desc: &str) -> String {
    let first = desc.lines().next().unwrap_or("").to_string();
    let count = first.chars().count();
    if count > 80 {
        let s: String = first.chars().take(83).collect();
        format!("{}...", s)
    } else {
        first
    }
}

struct Ctx<'a> {
    script_path: String,
    args: Vec<String>,
    root: &'a Command,
}

enum Plan {
    Items(Vec<CompItem>),
}

pub struct Output {
    pub items: Vec<CompItem>,
    pub prefix: String,       // assign/option prefix (e.g. "--oa=")
    pub delim_prefix: String, // delimiter prefix (e.g. "abc,")
    pub filter: String,
    pub cd: Option<String>,
    pub argc_prefix: String,
    pub suffix: String,
}

fn notation_value(n: &str) -> CompItem {
    CompItem::new(&format!("__argc_value={}", n), "", false, Color::Value)
}

fn run_fn(ctx: &Ctx, m: &Matcher, f: &str, cur: &str) -> Vec<String> {
    let shell = match crate::runner::get_shell_path() {
        Ok(s) => s,
        Err(_) => return vec![],
    };
    let vars = lenient_vars(m);
    let mut b64_src = vars.join(";");
    b64_src.push(';');
    let mut cmd = std::process::Command::new(&shell);
    cmd.arg("--noprofile").arg("--norc").arg(&ctx.script_path).arg("___internal___").arg(f);
    cmd.args(&ctx.args);
    cmd.env("ARGC_VARS", base64_encode(b64_src.as_bytes()));
    cmd.env("ARGC_OS", crate::runner::os_name());
    cmd.env("ARGC_COMPGEN", "1");
    cmd.env("ARGC_CWORD", cur);
    cmd.env("ARGC_LAST_ARG", ctx.args.last().cloned().unwrap_or_default());
    cmd.stdin(std::process::Stdio::null());
    cmd.stderr(std::process::Stdio::null());
    match cmd.output() {
        Ok(o) => String::from_utf8_lossy(&o.stdout).lines().map(|l| l.to_string()).collect(),
        Err(_) => vec![],
    }
}

fn value_candidates(
    ctx: &Ctx,
    m: &Matcher,
    choice: &Option<ChoiceValue>,
    delimiter: Option<char>,
    notation: &str,
    cur: &str,
    out: &mut Output,
) {
    let (delim_prefix, word) = match delimiter {
        Some(d) => match cur.rfind(d) {
            Some(pos) => (cur[..pos + d.len_utf8()].to_string(), cur[pos + d.len_utf8()..].to_string()),
            None => (String::new(), cur.to_string()),
        },
        None => (String::new(), cur.to_string()),
    };
    let used: Vec<String> = match delimiter {
        Some(d) if !delim_prefix.is_empty() => delim_prefix[..delim_prefix.len() - d.len_utf8()]
            .split(d)
            .map(|s| s.to_string())
            .collect(),
        _ => vec![],
    };
    let nospace = delimiter.is_some();
    match choice {
        Some(ChoiceValue::Values(values)) => {
            for v in values {
                if used.contains(v) {
                    continue;
                }
                out.items.push(CompItem::new(v, "", nospace, Color::Value));
            }
            out.filter = word;
            out.delim_prefix = delim_prefix;
        }
        Some(ChoiceValue::Fn(f, _)) => {
            let lines = run_fn(ctx, m, f, &word);
            let mut filter = word.clone();
            for line in lines {
                let line = line.trim();
                if let Some(rest) = line.strip_prefix("__argc_") {
                    out.items.push(CompItem::new(line, "", false, Color::Value));
                    if let Some(v) = rest.strip_prefix("prefix=") {
                        out.argc_prefix = v.to_string();
                    } else if let Some(v) = rest.strip_prefix("filter=") {
                        filter = v.to_string();
                    } else if let Some(v) = rest.strip_prefix("cd=") {
                        out.cd = Some(v.to_string());
                    } else if let Some(v) = rest.strip_prefix("suffix=") {
                        out.suffix = v.to_string();
                    }
                    continue;
                }
                let (value, desc) = match line.split_once('\t') {
                    Some((v, d)) => (v.trim().to_string(), d.trim().to_string()),
                    None => (line.to_string(), String::new()),
                };
                if used.contains(&value) {
                    continue;
                }
                out.items.push(CompItem::new(&value, &desc, nospace, Color::Value));
            }
            out.filter = filter;
            out.delim_prefix = delim_prefix;
        }
        None => {
            out.items.push(notation_value(notation));
            out.filter = word;
        }
    }
}

fn flag_candidates(cmd: &Command, used: &[usize], cur: &str, out: &mut Output) {
    for (idx, p) in cmd.flag_options.iter().enumerate() {
        if used.contains(&idx) && !p.multiple_occurs {
            continue;
        }
        let color = if p.flag { Color::Flag } else { Color::Option };
        let desc = truncate_desc(&p.describe);
        let mut names = vec![p.long_name()];
        if let Some(s) = &p.short {
            names.push(s.clone());
        }
        for (k, name) in names.iter().enumerate() {
            if !name.starts_with(cur) {
                continue;
            }
            if p.assigned {
                let value = if k == 0 && p.long_prefix.len() == 2 { format!("{}=", name) } else { name.clone() };
                out.items.push(CompItem::new(&value, &desc, true, color));
            } else {
                out.items.push(CompItem::new(name, &desc, false, color));
            }
        }
    }
}

fn subcommand_candidates(cmd: &Command, out: &mut Output) {
    let any_desc = cmd.subcommands.iter().any(|s| !s.describe.is_empty());
    for sub in &cmd.subcommands {
        let desc = truncate_desc(&sub.describe);
        out.items.push(CompItem::new(&sub.cmd_name(), &desc, false, Color::Command));
        for (a, _) in &sub.aliases {
            if a.chars().count() < 2 {
                continue;
            }
            out.items.push(CompItem::new(a, &desc, false, Color::Command));
        }
    }
    out.items.push(CompItem::new(
        "help",
        if any_desc { "Show help for a command" } else { "" },
        false,
        Color::Command,
    ));
}

fn positional_candidates(ctx: &Ctx, m: &Matcher, cur: &str, out: &mut Output) {
    let cmd = m.cmds.last().unwrap().0;
    if cmd.positionals.is_empty() {
        out.items.push(notation_value("path"));
        out.filter = cur.to_string();
        return;
    }
    let mut pos = m.positional_args.clone();
    pos.push(cur.to_string());
    let tmp = Matcher {
        root: m.root,
        args: m.args.clone(),
        cmds: m.cmds.clone(),
        flag_args: vec![],
        positional_args: pos,
        dashes: m.dashes.clone(),
        level_has_args: vec![],
        choice_values: Default::default(),
        symbols: vec![],
        flag_ends: vec![],
    };
    let matched = tmp.match_positionals();
    let idx = matched.len().saturating_sub(1);
    if idx < cmd.positionals.len() {
        let p = &cmd.positionals[idx];
        value_candidates(ctx, m, &p.choice, p.delimiter, &p.notation, cur, out);
    }
}

pub fn compgen_items(root: &Command, script_path: &str, args: &[String]) -> Output {
    let mut out = Output {
        items: vec![],
        prefix: String::new(),
        delim_prefix: String::new(),
        filter: String::new(),
        cd: None,
        argc_prefix: String::new(),
        suffix: String::new(),
    };
    let ctx = Ctx { script_path: script_path.to_string(), args: args.to_vec(), root };
    let len = args.len();
    let cur = args[len - 1].clone();
    let m = Matcher::new(root, &args[..len - 1]);
    let cmd = m.cur();
    let level = m.cmds.len() - 1;
    let consumed = len - 1;
    // pending option values
    if let Some((fa, end)) = m.flag_args[level].last().zip(m.flag_ends[level].last()) {
        if let Some(idx) = fa.param {
            let p = &cmd.flag_options[idx];
            if !p.flag && *end == consumed && fa.prefixed_key.is_none() && !fa.has_eq {
                let n = fa.values.len();
                if p.terminated || (n < p.num_args.1 && !(cur.len() > 1 && maybe_flag(signs_of(cmd), &cur))) {
                    if !p.assigned {
                        let notation = p.notations.get(n).or(p.notations.last()).cloned().unwrap_or_default();
                        value_candidates(&ctx, &m, &p.choice, p.delimiter, &notation, &cur, &mut out);
                        return out;
                    }
                }
            }
        }
    }
    let positional_mode = cmd.delegated()
        || !m.dashes.is_empty()
        || {
            if let Some(last) = cmd.positionals.last() {
                last.terminated && !m.positional_args.is_empty() && m.positional_args.len() + 1 >= cmd.positionals.len()
            } else {
                false
            }
        };
    if positional_mode {
        positional_candidates(&ctx, &m, &cur, &mut out);
        return out;
    }
    // symbols
    if let Some(c) = cur.chars().next() {
        if let Some((_, _, f)) = cmd.symbols.iter().find(|(sc, _, _)| *sc == c) {
            let word = &cur[c.len_utf8()..];
            out.prefix = c.to_string();
            if let Some(f) = f {
                value_candidates(&ctx, &m, &Some(ChoiceValue::Fn(f.clone(), true)), None, "", word, &mut out);
            }
            out.filter = word.to_string();
            return out;
        }
    }
    if cur.starts_with('-') {
        // option assign
        if let Some((k, v)) = cur.split_once('=') {
            if let Some(p) = cmd.flag_options.iter().find(|p| p.long_name() == k || p.short.as_deref() == Some(k)) {
                if !p.flag {
                    out.prefix = format!("{}=", k);
                    let notation = p.notations.first().cloned().unwrap_or_default();
                    value_candidates(&ctx, &m, &p.choice, p.delimiter, &notation, v, &mut out);
                }
            }
            return out;
        }
        // prefixed
        if let Some(p) = cmd.flag_options.iter().find(|p| p.prefixed && cur.starts_with(&p.long_name()) && cur.len() >= p.long_name().len() && !p.flag) {
            let ln = p.long_name();
            if cur != ln || true {
                out.prefix = ln.clone();
                let notation = p.notations.first().cloned().unwrap_or_default();
                value_candidates(&ctx, &m, &p.choice, p.delimiter, &notation, &cur[ln.len()..], &mut out);
                return out;
            }
        }
        let used: Vec<usize> = m.flag_args[level].iter().filter_map(|fa| fa.param).collect();
        // combine shorts
        if root.combine_shorts && cur.len() >= 2 && !cur.starts_with("--") {
            let chars: Vec<char> = cur.chars().skip(1).collect();
            let all_flags = chars.iter().all(|c| {
                let name = format!("-{}", c);
                cmd.flag_options.iter().any(|p| p.flag && (p.long_name() == name || p.short.as_deref() == Some(name.as_str())))
            });
            if all_flags && !chars.is_empty() {
                let mut used2 = used.clone();
                for c in &chars {
                    let name = format!("-{}", c);
                    if let Some(idx) = cmd.flag_options.iter().position(|p| p.long_name() == name || p.short.as_deref() == Some(name.as_str())) {
                        used2.push(idx);
                    }
                }
                if chars.len() == 1 {
                    out.items.push(CompItem::new(&cur, "", false, Color::Flag));
                }
                for (idx, p) in cmd.flag_options.iter().enumerate() {
                    if !p.flag || p.is_help || p.is_version || (used2.contains(&idx) && !p.multiple_occurs) {
                        continue;
                    }
                    let short = if p.is_single_long() { Some(p.long_name()) } else { p.short.clone() };
                    if let Some(s) = short {
                        if let Some(ch) = s.strip_prefix('-') {
                            out.items.push(CompItem::new(&format!("{}{}", cur, ch), &truncate_desc(&p.describe), false, Color::Flag));
                        }
                    }
                }
                out.filter = cur.clone();
                return out;
            }
        }
        flag_candidates(cmd, &used, &cur, &mut out);
        out.filter = cur.clone();
        return out;
    }
    // command or positional
    if m.positional_args.len() == 1 && m.positional_args[0] == "help" && !cmd.subcommands.is_empty() {
        subcommand_candidates(cmd, &mut out);
        out.filter = cur.clone();
        return out;
    }
    if m.positional_args.first().map(|v| v == "help").unwrap_or(false) && m.positional_args.len() >= 2 {
        out.items.push(notation_value("path"));
        out.filter = cur.clone();
        return out;
    }
    if !cmd.subcommands.is_empty() && m.positional_args.is_empty() {
        if !cmd.positionals.is_empty() {
            positional_candidates(&ctx, &m, &cur, &mut out);
        }
        let mut sub = Output { items: vec![], prefix: String::new(), delim_prefix: String::new(), filter: String::new(), cd: None, argc_prefix: String::new(), suffix: String::new() };
        subcommand_candidates(cmd, &mut sub);
        out.items.extend(sub.items);
        out.filter = cur.clone();
        return out;
    }
    if !cmd.subcommands.is_empty() && cmd.positionals.is_empty() {
        out.items.push(notation_value("path"));
        out.filter = cur.clone();
        return out;
    }
    positional_candidates(&ctx, &m, &cur, &mut out);
    out
}

fn filter_items(out: &Output) -> Vec<CompItem> {
    out.items
        .iter()
        .filter(|it| it.value.starts_with("__argc_") || it.value.starts_with(&out.filter))
        .cloned()
        .collect()
}

// ---------------- shells ----------------

fn escape_chars(value: &str, always: &str, at_start: &str, esc: &str) -> String {
    let mut out = String::new();
    for (i, c) in value.chars().enumerate() {
        if always.contains(c) || (i == 0 && at_start.contains(c)) {
            out.push_str(esc);
        }
        out.push(c);
    }
    out
}

fn quote_if(value: &str, always: &str, at_start: &str) -> String {
    let need = value.chars().enumerate().any(|(i, c)| always.contains(c) || (i == 0 && at_start.contains(c)));
    if need {
        format!("'{}'", value)
    } else {
        value.to_string()
    }
}

fn bash_escape(v: &str) -> String {
    escape_chars(v, " '\"$\\(&;!|<`>)", "#", "\\")
}

fn zsh_escape(v: &str) -> String {
    let mut out = String::new();
    for (i, c) in v.chars().enumerate() {
        if c == ':' {
            out.push('\\');
        } else if " '\"$\\(&;*?[!|<`>)".contains(c) || (i == 0 && "=#".contains(c)) {
            out.push_str("\\\\");
        }
        out.push(c);
    }
    out
}

fn tcsh_escape(v: &str) -> String {
    escape_chars(v, " '\"$\\(&;*?!|<{`>)", "", "\\").replace(' ', "\u{2800}")
}

fn nushell_escape(v: &str) -> String {
    quote_if(v, " '\"(;[|{`)}", "$#!")
}

fn powershell_escape(v: &str) -> String {
    quote_if(v, " '\"$(&;|{,`)}", "#<@>]")
}

fn xonsh_escape(v: &str) -> String {
    quote_if(v, " '\"(&;*[#!|<{`>)]}", ":=^")
}

fn common_prefix(values: &[String]) -> String {
    if values.is_empty() {
        return String::new();
    }
    let first: Vec<char> = values[0].chars().collect();
    let mut n = first.len();
    for v in &values[1..] {
        let cs: Vec<char> = v.chars().collect();
        let mut k = 0;
        while k < n && k < cs.len() && cs[k] == first[k] {
            k += 1;
        }
        n = k;
    }
    first[..n].iter().collect()
}

pub fn expand_argc_values(items: Vec<CompItem>, out: &Output) -> Vec<CompItem> {
    let mut result = vec![];
    for it in items {
        if let Some(kind) = it.value.strip_prefix("__argc_value=") {
            let upper = kind.to_uppercase();
            let mode = if upper.contains("PATH") || upper.contains("FILE") {
                Some(false)
            } else if upper.contains("DIR") || upper.contains("FOLDER") {
                Some(true)
            } else if upper.contains("ARG") || upper.contains("ANY") {
                Some(false)
            } else {
                None
            };
            if let Some(dirs_only) = mode {
                result.extend(list_paths(&out.filter, dirs_only, out.cd.as_deref()));
            }
            continue;
        }
        if it.value.starts_with("__argc_") {
            continue;
        }
        result.push(it);
    }
    result
}

fn list_paths(cur: &str, dirs_only: bool, cd: Option<&str>) -> Vec<CompItem> {
    let (dir_part, name_prefix) = match cur.rfind('/') {
        Some(pos) => (&cur[..pos + 1], &cur[pos + 1..]),
        None => ("", cur),
    };
    let mut base = if dir_part.is_empty() {
        ".".to_string()
    } else if let Some(rest) = dir_part.strip_prefix("~/") {
        format!("{}/{}", std::env::var("HOME").unwrap_or_default(), rest)
    } else {
        dir_part.to_string()
    };
    if let Some(cd) = cd {
        if !base.starts_with('/') {
            base = format!("{}/{}", cd, base);
        }
    }
    let mut entries: Vec<(String, bool, bool, bool)> = vec![];
    if let Ok(rd) = std::fs::read_dir(&base) {
        for e in rd.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            if !name.starts_with(name_prefix) {
                continue;
            }
            if name.starts_with('.') && !name_prefix.starts_with('.') {
                continue;
            }
            let path = e.path();
            let meta = match std::fs::metadata(&path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            let is_link = std::fs::symlink_metadata(&path).map(|m| m.file_type().is_symlink()).unwrap_or(false);
            let is_dir = meta.is_dir();
            use std::os::unix::fs::PermissionsExt;
            let is_exe = !is_dir && meta.permissions().mode() & 0o111 != 0;
            if dirs_only && !is_dir {
                continue;
            }
            entries.push((name, is_dir, is_exe, is_link));
        }
    }
    entries.sort_by(|a, b| a.0.to_lowercase().cmp(&b.0.to_lowercase()).then(a.0.cmp(&b.0)));
    let mut items = vec![];
    for (name, is_dir, is_exe, is_link) in entries {
        let display = if is_dir { format!("{}/", name) } else { name.clone() };
        let color = if is_dir {
            Color::Dir
        } else if is_link {
            Color::Symlink
        } else if is_exe {
            Color::Exe
        } else {
            Color::Value
        };
        items.push(CompItem {
            value: format!("{}{}", dir_part, display),
            display: Some(display),
            desc: String::new(),
            nospace: is_dir,
            color,
        });
    }
    items
}

pub fn format_output(shell: &str, out: Output) -> String {
    let items = filter_items(&out);
    let suffix = out.suffix.clone();
    let mut lines: Vec<String> = vec![];
    if shell == "generic" {
        for it in &items {
            let v = if it.value.starts_with("__argc_") { it.value.clone() } else { format!("{}{}", it.value, suffix) };
            let mut s = v;
            if it.nospace {
                s.push('\0');
            }
            s.push_str("\t/color:");
            s.push_str(it.color.generic());
            if !it.desc.is_empty() {
                s.push('\t');
                s.push_str(&it.desc);
            }
            lines.push(s);
        }
        return join_lines(lines);
    }
    let path_mode = items.iter().any(|it| it.value.starts_with("__argc_value="));
    let items = expand_argc_values(items, &out);
    let full_prefix = format!("{}{}", out.argc_prefix, out.prefix);
    match shell {
        "bash" => {
            let values: Vec<String> = items.iter().map(|it| format!("{}{}", it.display(), suffix)).collect();
            if items.len() > 1 {
                let cp = common_prefix(&values);
                let filter_len = if path_mode {
                    out.filter.rsplit('/').next().unwrap_or("").chars().count()
                } else {
                    out.filter.chars().count()
                };
                if cp.chars().count() > filter_len {
                    return join_lines(vec![bash_escape(&cp)]);
                }
            }
            let n = items.len();
            for (it, v) in items.iter().zip(values.iter()) {
                let mut s = bash_escape(v);
                if n > 1 && !it.desc.is_empty() {
                    s.push_str(&format!(" ({})", it.desc));
                } else if !it.nospace {
                    s.push(' ');
                }
                lines.push(s);
            }
        }
        "zsh" => {
            for it in &items {
                let value = format!("{}{}{}{}", full_prefix, out.delim_prefix, it.value, suffix);
                let display = format!("{}{}", it.display(), suffix);
                let mut s = zsh_escape(&value);
                if !it.nospace {
                    s.push(' ');
                }
                s.push('\t');
                s.push_str(&display.replace(':', "\\:"));
                if !it.desc.is_empty() {
                    s.push(':');
                    s.push_str(&it.desc);
                }
                s.push('\t');
                s.push_str(&display);
                s.push('\t');
                s.push_str(it.color.ansi());
                lines.push(s);
            }
        }
        "fish" => {
            for it in &items {
                let mut s = format!("{}{}{}{}", full_prefix, out.delim_prefix, it.value, suffix);
                if !it.desc.is_empty() {
                    s.push('\t');
                    s.push_str(&it.desc);
                }
                lines.push(s);
            }
        }
        "nushell" => {
            for it in &items {
                let value = format!("{}{}{}{}", full_prefix, out.delim_prefix, it.value, suffix);
                let mut s = nushell_escape(&value);
                if !it.nospace {
                    s.push(' ');
                }
                if !it.desc.is_empty() {
                    s.push('\t');
                    s.push_str(&it.desc);
                }
                lines.push(s);
            }
        }
        "powershell" => {
            for it in &items {
                let value = format!("{}{}{}", full_prefix, it.value, suffix);
                let display = format!("{}{}", it.display(), suffix);
                lines.push(format!(
                    "{}\t{}\t{}\t{}\t{}",
                    powershell_escape(&value),
                    if it.nospace { 0 } else { 1 },
                    display,
                    it.desc,
                    it.color.ansi()
                ));
            }
        }
        "elvish" => {
            for it in &items {
                let value = format!("{}{}{}{}", full_prefix, out.delim_prefix, it.value, suffix);
                let display = format!("{}{}", it.display(), suffix);
                lines.push(format!(
                    "{}\t{}\t{}\t{}\t{}",
                    value,
                    if it.nospace { 0 } else { 1 },
                    display,
                    it.desc,
                    it.color.elvish()
                ));
            }
        }
        "xonsh" => {
            for it in &items {
                let value = format!("{}{}{}{}", full_prefix, out.delim_prefix, it.value, suffix);
                let display = format!("{}{}", it.display(), suffix);
                lines.push(format!(
                    "{}\t{}\t{}\t{}",
                    xonsh_escape(&value),
                    if it.nospace { 0 } else { 1 },
                    display,
                    it.desc
                ));
            }
        }
        "tcsh" => {
            let n = items.len();
            for it in &items {
                let value = format!("{}{}{}{}", full_prefix, out.delim_prefix, it.value, suffix);
                let mut s = tcsh_escape(&value);
                if n > 1 && !it.desc.is_empty() {
                    s.push('\u{2800}');
                    s.push_str(&format!("({})", it.desc).replace(' ', "\u{2800}"));
                }
                lines.push(s);
            }
        }
        _ => {}
    }
    join_lines(lines)
}

fn join_lines(lines: Vec<String>) -> String {
    if lines.is_empty() {
        return String::new();
    }
    let mut s = lines.join("\n");
    s.push('\n');
    s
}

pub const SHELLS: [&str; 9] = ["bash", "zsh", "fish", "nushell", "powershell", "elvish", "xonsh", "tcsh", "generic"];

