{"command":"cat > /workspace/src/bundle.rs <<'EOF'
use crate::build_helpers::*;
use crate::command::Command;
use crate::help::{render_help, render_version};
use crate::param::*;
use crate::parser::{ChoiceValue, DefaultValue};
use crate::utils::escape_shell_words;

#[derive(Default)]
struct Needs {
    take_args: bool,
    match_positionals: bool,
    split_positionals: bool,
    validate_choices: bool,
    check_bool: bool,
    maybe_flag_option: bool,
    require_params: bool,
}

fn suffix(cmd: &Command) -> String {
    if cmd.paths.is_empty() {
        String::new()
    } else {
        format!("_{}", cmd.paths.join("_"))
    }
}

fn choices_expr(choice: &Option<ChoiceValue>) -> Option<String> {
    match choice {
        Some(ChoiceValue::Values(vs)) => {
            let list: Vec<String> = vs.iter().map(|v| escape_shell_words(v)).collect();
            Some(format!("$(printf \"%s\\n\" {})", list.join(" ")))
        }
        Some(ChoiceValue::Fn(f, true)) => Some(format!("$({})", f)),
        _ => None,
    }
}

fn default_expr(default: &Option<DefaultValue>) -> Option<String> {
    match default {
        Some(DefaultValue::Value(v)) => Some(escape_shell_words(v)),
        Some(DefaultValue::Fn(f)) => Some(format!("\"$({})\"", f)),
        None => None,
    }
}

fn signs(cmd: &Command) -> String {
    let mut minus = false;
    let mut plus = false;
    for p in &cmd.flag_options {
        for n in p.list_names() {
            if n.starts_with('+') {
                plus = true;
            } else if n.starts_with('-') {
                minus = true;
            }
        }
    }
    let mut s = String::new();
    if minus {
        s.push('-');
    }
    if plus {
        s.push('+');
    }
    s
}

fn has_user_flags(cmd: &Command) -> bool {
    cmd.flag_options.iter().any(|p| !p.is_help && !p.is_version)
}

fn walk<'a>(cmd: &'a Command, out: &mut Vec<&'a Command>) {
    out.push(cmd);
    for s in &cmd.subcommands {
        walk(s, out);
    }
}

pub fn build(source: &str, root: &Command) -> String {
    let mut cmds = vec![];
    walk(root, &mut cmds);
    let mut needs = Needs::default();
    let mut body: Vec<String> = vec![];
    for cmd in &cmds {
        body.push(gen_usage(cmd));
        if cmd.flag_options.iter().any(|p| p.is_version) {
            body.push(gen_version(cmd));
        }
        body.push(gen_parse(cmd, root, &mut needs));
    }
    let mut block: Vec<String> = vec![];
    block.push("# ARGC-BUILD {\n# This block was generated by argc (https://github.com/sigoden/argc).\n# Modifying it manually is not recommended".to_string());
    block.push(gen_run(root, &needs));
    block.extend(body);
    if needs.take_args {
        block.push(H_TAKE_ARGS.to_string());
    }
    if needs.match_positionals {
        block.push(H_MATCH_POSITIONALS.to_string());
    }
    if needs.split_positionals {
        block.push(H_SPLIT_POSITIONALS.to_string());
    }
    if needs.validate_choices {
        block.push(H_VALIDATE_CHOICES.to_string());
    }
    if needs.check_bool {
        block.push(H_CHECK_BOOL.to_string());
    }
    if needs.maybe_flag_option {
        block.push(H_MAYBE_FLAG_OPTION.to_string());
    }
    if root.dotenv.is_some() {
        block.push(H_LOAD_DOTENV.to_string());
    }
    if needs.require_params {
        block.push(H_REQUIRE_PARAMS.to_string());
    }
    if any_tools(root) {
        block.push(H_REQUIRE_TOOLS.to_string());
    }
    block.push(H_DIE.to_string());
    block.push("_argc_run \"$@\"".to_string());
    block.push("# ARGC-BUILD }".to_string());
    let block = block.join("\n\n");

    // replace eval line
    let mut out = String::new();
    let mut replaced = false;
    let mut rest = source;
    while !rest.is_empty() {
        let (line, nl) = match rest.find('\n') {
            Some(pos) => (&rest[..pos], &rest[pos..pos + 1]),
            None => (rest, ""),
        };
        let consumed = line.len() + nl.len();
        if !replaced && is_eval_line(line) {
            out.push_str(&block);
            replaced = true;
        } else {
            out.push_str(line);
        }
        out.push_str(nl);
        rest = &rest[consumed..];
    }
    if !replaced {
        out.push('\n');
        out.push_str(&block);
    }
    out
}

fn is_eval_line(line: &str) -> bool {
    let t = line.trim_start();
    t.starts_with("eval") && t.contains("argc --argc-eval \"$0\" \"$@\"")
}

fn any_tools(cmd: &Command) -> bool {
    !cmd.require_tools.is_empty() || cmd.subcommands.iter().any(any_tools)
}

fn any_required_flags(cmd: &Command) -> bool {
    cmd.flag_options.iter().any(|p| p.required) || cmd.subcommands.iter().any(any_required_flags)
}

fn any_required_envs(cmd: &Command) -> bool {
    cmd.envs.iter().any(|p| p.required) || cmd.subcommands.iter().any(any_required_envs)
}

fn gen_run(root: &Command, _needs: &Needs) -> String {
    let mut s = String::from(
        r#"_argc_run() {
    if [[ "${1:-}" == "___internal___" ]]; then
        _argc_die "error: unsupported ___internal___ command"
    fi
    if [[ "${OS:-}" == "Windows_NT" ]] && [[ -n "${MSYSTEM:-}" ]]; then
        set -o igncr
    fi
    argc__args=("$(basename "$0" .sh)" "$@")
    argc__positionals=()
    _argc_index=1
    _argc_len="${#argc__args[@]}"
"#,
    );
    if let Some(d) = &root.dotenv {
        s.push_str(&format!("    _argc_load_dotenv {}\n", escape_shell_words(d)));
    }
    s.push_str("    _argc_required_flag_options=()\n    _argc_required_envs=()\n    _argc_tools=()\n    _argc_parse\n");
    if any_required_flags(root) {
        s.push_str("    _argc_require_params \"error: the following required arguments were not provided:\" \"${_argc_required_flag_options[@]}\"\n");
    }
    if any_required_envs(root) {
        s.push_str("    _argc_require_params \"error: the following required environments were not provided:\" \"${_argc_required_envs[@]}\"\n");
    }
    if any_tools(root) {
        s.push_str("    _argc_require_tools \"${_argc_tools[@]}\"\n");
    }
    if let Some(h) = &root.before_hook {
        s.push_str(&format!("    {}\n", h));
    }
    s.push_str("    if [ -n \"${argc__fn:-}\" ]; then\n        $argc__fn \"${argc__positionals[@]}\"\n");
    if let Some(h) = &root.after_hook {
        s.push_str(&format!("    {}\n", h));
    }
    s.push_str("    fi\n}");
    s
}

fn gen_usage(cmd: &Command) -> String {
    let help = render_help(cmd);
    format!(
        "_argc_usage{}() {{\n    cat <<-'EOF'\n{}\nEOF\n    exit\n}}",
        suffix(cmd),
        help.trim_end_matches('\n')
    )
}

fn gen_version(cmd: &Command) -> String {
    format!("_argc_version{}() {{\n    echo {}\n    exit\n}}", suffix(cmd), render_version(cmd))
}

fn gen_parse(cmd: &Command, root: &Command, needs: &mut Needs) -> String {
    let sfx = suffix(cmd);
    let mut s = String::new();
    s.push_str(&format!("_argc_parse{}() {{\n", sfx));
    s.push_str("    local _argc_key _argc_action\n");
    s.push_str(&format!("    local _argc_subcmds=\"{}\"\n", cmd.list_subcommand_names().join(", ")));
    s.push_str("    while [[ $_argc_index -lt $_argc_len ]]; do\n");
    s.push_str("        _argc_item=\"${argc__args[_argc_index]}\"\n");
    s.push_str("        _argc_key=\"${_argc_item%%=*}\"\n");
    s.push_str("        case \"$_argc_key\" in\n");
    // help
    if let Some(h) = cmd.flag_options.iter().find(|p| p.is_help) {
        let mut names = "--help | -help".to_string();
        if h.short.as_deref() == Some("-h") {
            names.push_str(" | -h");
        }
        s.push_str(&format!("        {})\n            _argc_usage{}\n            ;;\n", names, sfx));
    }
    if let Some(v) = cmd.flag_options.iter().find(|p| p.is_version) {
        let mut names = "--version | -version".to_string();
        if v.short.as_deref() == Some("-V") {
            names.push_str(" | -V");
        }
        s.push_str(&format!("        {})\n            _argc_version{}\n            ;;\n", names, sfx));
    }
    s.push_str("        --)\n            _argc_dash=\"${#argc__positionals[@]}\"\n            argc__positionals+=(\"${argc__args[@]:$((_argc_index + 1))}\")\n            _argc_index=$_argc_len\n            break\n            ;;\n");
    let sg = signs(cmd);
    for p in cmd.flag_options.iter().filter(|p| !p.is_help && !p.is_version) {
        let names = p.list_names().join(" | ");
        let var = p.var_name();
        let long = p.long_name();
        s.push_str(&format!("        {})\n", names));
        if p.flag {
            s.push_str(&format!(
                "            if [[ \"$_argc_item\" == *=* ]]; then\n                _argc_die \"error: flag \\`{}\\` don't accept any value\"\n            fi\n",
                long
            ));
            s.push_str("            _argc_index=$((_argc_index + 1))\n");
            s.push_str(&format!("            if [[ -n \"${{{}:-}}\" ]]; then\n", var));
            if p.multiple_occurs {
                s.push_str(&format!("                {}=$(({} + 1))\n", var, var));
            } else {
                s.push_str(&format!(
                    "                _argc_die \"error: the argument \\`{}\\` cannot be used multiple times\"\n",
                    long
                ));
            }
            s.push_str(&format!("            else\n                {}=1\n            fi\n", var));
        } else {
            needs.take_args = true;
            let delim = p.delimiter.map(|c| c.to_string()).unwrap_or_default();
            let take = format!(
                "_argc_take_args \"{}\" {} {} \"{}\" \"{}\"",
                p.render_long_name_notations(),
                p.num_args.0,
                p.num_args.1,
                if p.terminated { "" } else { sg.as_str() },
                delim
            );
            if p.assigned {
                s.push_str(&format!(
                    "            if [[ \"$_argc_key\" == \"$_argc_item\" ]]; then\n                _argc_die \"error: incorrect number of values for \\`{}\\`\"\n            else\n                {}\n            fi\n",
                    p.render_long_name_notations(),
                    take
                ));
            } else {
                s.push_str(&format!("            {}\n", take));
            }
            s.push_str("            _argc_index=$((_argc_index + _argc_take_args_len + 1))\n");
            if let Some(expr) = choices_expr(&p.choice) {
                needs.validate_choices = true;
                s.push_str(&format!(
                    "            _argc_validate_choices '`{}`' \"{}\" \"${{_argc_take_args_values[@]}}\"\n",
                    p.render_first_notation(),
                    expr
                ));
            }
            if p.multiple_values {
                s.push_str(&format!("            {}+=(\"${{_argc_take_args_values[@]}}\")\n", var));
            } else {
                s.push_str(&format!(
                    "            if [[ -z \"${{{}:-}}\" ]]; then\n                {}=\"${{_argc_take_args_values[0]:-}}\"\n            else\n                _argc_die \"error: the argument \\`{}\\` cannot be used multiple times\"\n            fi\n",
                    var, var, long
                ));
            }
        }
        s.push_str("            ;;\n");
    }
    for sub in &cmd.subcommands {
        let mut names = vec![sub.cmd_name()];
        names.extend(sub.alias_names());
        s.push_str(&format!(
            "        {})\n            _argc_index=$((_argc_index + 1))\n            _argc_action=_argc_parse{}\n            break\n            ;;\n",
            names.join(" | "),
            suffix(sub)
        ));
    }
    if !cmd.subcommands.is_empty() {
        s.push_str("        help)\n            local help_arg=\"${argc__args[$((_argc_index + 1))]:-}\"\n            case \"$help_arg\" in\n");
        for sub in &cmd.subcommands {
            let mut names = vec![sub.cmd_name()];
            names.extend(sub.alias_names());
            s.push_str(&format!("            {})\n                _argc_usage{}\n                ;;\n", names.join(" | "), suffix(sub)));
        }
        s.push_str(&format!("            \"\")\n                _argc_usage{}\n                ;;\n", sfx));
        s.push_str("            *)\n                _argc_die \"error: invalid value \\`$help_arg\\` for \\`<command>\\`\"$'\\n'\"  [possible values: $_argc_subcmds]\"\n                ;;\n            esac\n            ;;\n");
    }
    s.push_str("        *)\n");
    if has_user_flags(cmd) {
        needs.maybe_flag_option = true;
        s.push_str(&format!(
            "            if _argc_maybe_flag_option \"{}\" \"$_argc_item\"; then\n                _argc_die \"error: unexpected argument \\`$_argc_key\\` found\"\n            fi\n",
            sg
        ));
    }
    if !cmd.subcommands.is_empty() {
        if let Some(def) = cmd.find_default_subcommand() {
            s.push_str(&format!(
                "            if [[ \"${{#argc__positionals[@]}}\" -eq 0 ]]; then\n                _argc_action=_argc_parse{}\n                break\n            fi\n",
                suffix(def)
            ));
        } else if !cmd.positionals.is_empty() {
            s.push_str("            argc__positionals+=(\"$_argc_item\")\n            _argc_index=$((_argc_index + 1))\n");
        } else {
            s.push_str(&format!(
                "            _argc_die \"error: \\`{}\\` requires a subcommand but one was not provided\"$'\\n'\"  [subcommands: $_argc_subcmds]\"\n",
                cmd.full_name()
            ));
        }
    } else {
        s.push_str("            argc__positionals+=(\"$_argc_item\")\n            _argc_index=$((_argc_index + 1))\n");
    }
    s.push_str("            ;;\n        esac\n    done\n");
    // post
    for p in cmd.flag_options.iter().filter(|p| !p.is_help && !p.is_version) {
        let Some(env) = &p.env else { continue };
        let var = p.var_name();
        if p.flag {
            needs.check_bool = true;
            s.push_str(&format!(
                "    if [[ -z \"${{{var}:-}}\" ]] && [[ -n \"${{{env}:-}}\" ]]; then\n        if _argc_check_bool {env} \"{long}\"; then\n            {var}=1\n        fi\n    fi\n",
                var = var,
                env = env,
                long = p.long_name()
            ));
        } else {
            s.push_str(&format!("    if [[ -z \"${{{}:-}}\" ]] && [[ -n \"${{{}:-}}\" ]]; then        \n", var, env));
            match p.delimiter {
                Some(d) => s.push_str(&format!("        IFS=\"{}\" read -r -a _argc_env_values <<<\"${}\"\n", d, env)),
                None => s.push_str(&format!("        _argc_env_values=(\"${}\")\n", env)),
            }
            if let Some(expr) = choices_expr(&p.choice) {
                needs.validate_choices = true;
                s.push_str(&format!(
                    "        _argc_validate_choices 'environment variable `{}` that bound to `{}`' \"{}\" \"${{_argc_env_values[@]}}\"\n",
                    env,
                    p.render_long_name_notations(),
                    expr
                ));
            }
            if p.multiple_values {
                s.push_str(&format!("        {}=(\"${{_argc_env_values[@]}}\")\n", var));
            } else {
                s.push_str(&format!("        {}=\"${{_argc_env_values[0]}}\"\n", var));
            }
            s.push_str("    fi\n");
        }
    }
    for p in cmd.flag_options.iter().filter(|p| !p.is_help && !p.is_version) {
        if let Some(expr) = default_expr(&p.default) {
            let var = p.var_name();
            s.push_str(&format!("    if [[ -z \"${{{}:-}}\" ]]; then\n        {}={}\n    fi\n", var, var, expr));
        }
    }
    let required: Vec<String> = cmd
        .flag_options
        .iter()
        .filter(|p| p.required)
        .map(|p| format!("'{}:{}'", p.var_name(), p.render_long_name_notations()))
        .collect();
    if !required.is_empty() {
        needs.require_params = true;
        s.push_str(&format!("    _argc_required_flag_options+=({})\n", required.join(" ")));
    }
    let mut tools: Vec<String> = vec![];
    {
        // accumulate tools from root to this cmd
        let mut c = root;
        tools.extend(c.require_tools.iter().cloned());
        for name in &cmd.paths {
            if let Some(next) = c.subcommands.iter().find(|s| &s.cmd_name() == name) {
                c = next;
                tools.extend(c.require_tools.iter().cloned());
            }
        }
    }
    if !tools.is_empty() {
        s.push_str(&format!("    _argc_tools=({})\n", tools.join(" ")));
    }
    s.push_str("    if [[ -n \"${_argc_action:-}\" ]]; then\n        $_argc_action\n    else\n");
    if !cmd.subcommands.is_empty() && cmd.command_fn.is_none() && cmd.positionals.is_empty() {
        s.push_str(&format!("        _argc_usage{}\n", sfx));
    } else {
        if let Some(f) = &cmd.command_fn {
            s.push_str(&format!("        argc__fn={}\n", f));
        }
        s.push_str(&format!(
            "        if [[ \"${{argc__positionals[0]:-}}\" == \"help\" ]] && [[ \"${{#argc__positionals[@]}}\" -eq 1 ]]; then\n            _argc_usage{}\n        fi\n",
            sfx
        ));
        if !cmd.positionals.is_empty() {
            needs.match_positionals = true;
            let flags: Vec<&str> = cmd.positionals.iter().map(|p| if p.multiple { "1" } else { "0" }).collect();
            s.push_str(&format!("        _argc_match_positionals {}\n", flags.join(" ")));
            s.push_str("        local values_index values_size\n");
            for (i, p) in cmd.positionals.iter().enumerate() {
                let var = p.var_name();
                s.push_str(&format!(
                    "        IFS=: read -r values_index values_size <<<\"${{_argc_match_positionals_values[{}]:-}}\"\n",
                    i
                ));
                s.push_str("        if [[ -n \"$values_index\" ]]; then\n");
                if p.multiple {
                    if let Some(d) = p.delimiter {
                        needs.split_positionals = true;
                        s.push_str(&format!(
                            "            _argc_split_positionals \"$values_index\" \"$values_size\" \"{}\"\n            {}=(\"${{_argc_split_positionals_values[@]}}\")\n",
                            d, var
                        ));
                    } else {
                        s.push_str(&format!("            {}=(\"${{argc__positionals[@]:values_index:values_size}}\")\n", var));
                    }
                } else {
                    s.push_str(&format!("            {}=\"${{argc__positionals[values_index]}}\"\n", var));
                }
                if let Some(expr) = choices_expr(&p.choice) {
                    needs.validate_choices = true;
                    let target = if p.multiple { format!("${{{}[@]}}", var) } else { format!("${}", var) };
                    s.push_str(&format!(
                        "            _argc_validate_choices '`{}`' \"{}\" \"{}\"\n",
                        p.render_notation(),
                        expr,
                        target
                    ));
                }
                if let Some(env) = &p.env {
                    s.push_str(&format!("        elif [[ -n \"${{{}:-}}\" ]]; then            \n", env));
                    match p.delimiter {
                        Some(d) => s.push_str(&format!("            IFS=\"{}\" read -r -a _argc_env_values <<<\"${}\"\n", d, env)),
                        None => s.push_str(&format!("            _argc_env_values=(\"${}\")\n", env)),
                    }
                    if let Some(expr) = choices_expr(&p.choice) {
                        needs.validate_choices = true;
                        s.push_str(&format!(
                            "            _argc_validate_choices 'environment variable `{}` that bound to `{}`' \"{}\" \"${{_argc_env_values[@]}}\"\n",
                            env,
                            p.render_notation(),
                            expr
                        ));
                    }
                    if p.multiple {
                        s.push_str(&format!("            {}=(\"${{_argc_env_values[@]}}\")\n", var));
                    } else {
                        s.push_str(&format!("            {}=\"${{_argc_env_values[0]}}\"\n", var));
                    }
                    s.push_str("            argc__positionals+=(\"${_argc_env_values[@]}\")\n");
                }
                if let Some(expr) = default_expr(&p.default) {
                    s.push_str(&format!("        else\n            {}={}\n            argc__positionals+=(\"${}\")\n", var, expr, var));
                } else if p.required {
                    s.push_str(&format!(
                        "        else\n            _argc_die \"error: the required environments \\`{}\\` were not provided\"\n",
                        p.render_notation()
                    ));
                }
                s.push_str("        fi\n");
            }
        }
        // envs
        let req: Vec<String> = cmd.envs.iter().filter(|e| e.required).map(|e| format!("{}:{}", e.id, e.id)).collect();
        if !req.is_empty() {
            needs.require_params = true;
            s.push_str(&format!("        _argc_required_envs=({})\n", req.join(" ")));
        }
        for e in &cmd.envs {
            let dexpr = default_expr(&e.default);
            let cexpr = choices_expr(&e.choice);
            if cexpr.is_some() {
                needs.validate_choices = true;
            }
            let validate = cexpr.map(|expr| {
                format!(
                    "_argc_validate_choices 'environment variable `{}`' \"{}\" \"${}\"",
                    e.id, expr, e.id
                )
            });
            match (dexpr, validate) {
                (Some(d), Some(v)) => s.push_str(&format!(
                    "        if [[ -z \"${{{id}:-}}\" ]]; then\n            export {id}={d}\n        else\n            {v}\n        fi\n",
                    id = e.id,
                    d = d,
                    v = v
                )),
                (Some(d), None) => s.push_str(&format!(
                    "        if [[ -z \"${{{id}:-}}\" ]]; then\n            export {id}={d}\n        fi\n",
                    id = e.id,
                    d = d
                )),
                (None, Some(v)) => s.push_str(&format!(
                    "        if [[ -n \"${{{id}:-}}\" ]]; then\n            {v}\n        fi\n",
                    id = e.id,
                    v = v
                )),
                (None, None) => {}
            }
        }
    }
    s.push_str("    fi\n}");
    s
}
