pub const ARGCFILE_NAMES: [&str; 6] = ["Argcfile.sh", "Argcfile", "argcfile.sh", "argcfile", "ARGCFILE.sh", "ARGCFILE"];

pub fn find_argcfile(start: &Path) -> Option<PathBuf> {
    let mut dir = Some(start.to_path_buf());
    while let Some(d) = dir {
        for name in ARGCFILE_NAMES.iter() {
            let p = d.join(name);
            if p.is_file() {
                return Some(p);
            }
        }
        dir = d.parent().map(|v| v.to_path_buf());
    }
    None
}

pub fn run_script(script: &Path, args: &[String]) -> Result<i32, String> {
    let shell = get_shell_path()?;
    let cwd = std::env::current_dir().map_err(|e| e.to_string())?;
    let script_abs = if script.is_absolute() { script.to_path_buf() } else { cwd.join(script) };
    let script_dir = script_abs.parent().map(|v| v.to_path_buf()).unwrap_or_else(|| cwd.clone());
    let mut cmd = std::process::Command::new(&shell);
    cmd.arg(&script_abs);
    cmd.args(args);
    cmd.current_dir(&script_dir);
    cmd.env("ARGC_PWD", &cwd);
    let status = cmd.status().map_err(|e| format!("Failed to run '{}', {}", script_abs.display(), e))?;
    Ok(status.code().unwrap_or(1))
}

pub fn create_argcfile(recipes: &[String]) -> Result<i32, String> {
    let cwd = std::env::current_dir().map_err(|e| e.to_string())?;
    for name in ARGCFILE_NAMES.iter() {
        let p = cwd.join(name);
        if p.exists() {
            return Err(format!("Already exist {}", p.display()));
        }
    }
    let mut content = String::from("#!/usr/bin/env bash\n\nset -e\n\n");
    for r in recipes {
        content.push_str(&format!("# @cmd\n{}() {{\n    echo TODO {}\n}}\n\n", r, r));
    }
    content.push_str("# See more details at https://github.com/sigoden/argc\neval \"$(argc --argc-eval \"$0\" \"$@\")\"\n");
    let path = cwd.join("Argcfile.sh");
    std::fs::write(&path, content).map_err(|e| format!("Failed to write '{}', {}", path.display(), e))?;
    println!("Argcfile.sh has been successfully created.");
    Ok(0)
}

pub fn parallel(script: &str, args: &[String]) -> Result<i32, String> {
    let shell = get_shell_path()?;
    let mut jobs: Vec<Vec<String>> = vec![];
    let mut cur: Vec<String> = vec![];
    for a in args {
        if a == ":::" {
            if !cur.is_empty() {
                jobs.push(std::mem::take(&mut cur));
            }
        } else {
            cur.push(a.clone());
        }
    }
    if !cur.is_empty() {
        jobs.push(cur);
    }
    let handles: Vec<_> = jobs
        .into_iter()
        .map(|job| {
            let shell = shell.clone();
            let script = script.to_string();
            std::thread::spawn(move || {
                let mut cmd = std::process::Command::new(&shell);
                cmd.arg("--noprofile").arg("--norc").arg(&script).arg("___parallel___");
                cmd.args(&job);
                cmd.env("ARGC_PARALLEL", "1");
                cmd.stderr(std::process::Stdio::inherit());
                cmd.stdin(std::process::Stdio::null());
                match cmd.output() {
                    Ok(o) => (o.stdout, o.status.success()),
                    Err(_) => (vec![], false),
                }
            })
        })
        .collect();
    let mut ok = true;
    use std::io::Write;
    let mut stdout = std::io::stdout();
    for h in handles {
        if let Ok((out, success)) = h.join() {
            let _ = stdout.write_all(&out);
            let _ = stdout.flush();
            if !success {
                ok = false;
            }
        } else {
            ok = false;
        }
    }
    Ok(if ok { 0 } else { 1 })
}
